L["0 hides the bar between casts."] = "0이면 시전 사이에 막대를 숨깁니다."
L["0 hugs the entries. More keeps the window at least that tall."] = "0이면 항목에 맞춥니다. 더 크면 창이 최소한 그 높이를 유지합니다."
L["0 is normal. A higher priority wins the screen spot and is the last out of a full queue. Ties follow Overlap Behavior."] = "0이 보통입니다. 우선순위가 높으면 화면 자리를 차지하고 가득 찬 대기열에서 가장 나중에 빠집니다. 같으면 겹침 동작을 따릅니다."
L["0 keeps a ping until newer ones push it out."] = "0이면 새 핑이 밀어낼 때까지 핑을 유지합니다."
