L["1 group"] = "그룹 1개"
L["1 icon"] = "아이콘 1개"
L["1 icon in it is set to not displayed in your Cooldown Manager, so it stays out."] = "여기 있는 아이콘 1개는 재사용 대기시간 관리자에서 '표시 안 됨'으로 설정되어 있어 제외됩니다."
L["1 kind"] = "1종류"
L["1 layout hidden here. Show it"] = "여기에서 숨긴 구성 1개. 다시 보이기"
