L["1 of them is in Arc Auras already: importing again adds a second copy."] = "이 중 1개는 이미 Arc Auras에 있습니다. 다시 가져오면 사본이 하나 더 추가됩니다."
L["1 profile"] = "프로필 1개"
L["1 reminder"] = "알림 1개"
L["1 rule"] = "규칙 1개"
L["1 setting differs from the group; a cyan bar marks it."] = "설정 1개가 그룹과 다릅니다. 청록색 막대로 표시됩니다."
L["1 texture"] = "텍스처 1개"
L["3 to 10, spot 1 at the top. Fewer spots keep what sat on the others: it comes back with more."] = "3~10. 1번 칸이 맨 위입니다. 칸을 줄여도 다른 칸에 있던 항목은 그대로 보존되며, 칸을 다시 늘리면 돌아옵니다."
L["30 is a debuff's pandemic window. Needs no length."] = "30은 약화 효과의 확산 구간입니다. 길이를 입력할 필요가 없습니다."
L[": matches again ("] = ": matches again ("
L["A 2.6 second timer that runs out and starts again."] = "끝나면 다시 시작하는 2.6초 타이머입니다."
L["A Cooldown Manager icon"] = "재사용 대기시간 관리자 아이콘"
L["A Custom Icon or Bar"] = "사용자 설정 아이콘 또는 막대"
L["A Custom Icon or Bar's value"] = "사용자 설정 아이콘 또는 막대의 값"
L["A Dynamic aura group only tracks you, your pet and your target."] = "동적 오라 그룹은 자신, 소환수, 대상만 추적합니다."
L["A Dynamic group only tracks you, your pet and your target: turn its Dynamic off."] = "동적 그룹은 자신, 소환수, 대상만 추적합니다. 그룹의 동적을 끄십시오."
L["A blank layout. Add your own groups, icons and bars."] = "빈 구성입니다. 그룹, 아이콘, 막대를 직접 추가하십시오."
L["A buff or debuff as an icon; several IDs can light one icon."] = "강화 또는 약화 효과를 아이콘으로 표시합니다. 여러 ID로 하나의 아이콘을 표시할 수 있습니다."
L["A cast that finishes, one that is interrupted, then a channel."] = "끝까지 시전되는 주문, 차단당하는 주문, 그다음 정신 집중 주문입니다."
L["A cast while it runs: start it over, add the seconds to what is left, leave it running, or end it."] = "진행 중인 시전: 처음부터 다시 시작하거나, 남은 시간에 초를 더하거나, 그대로 진행하거나, 종료합니다."
L["A charge left and another coming back, over and over: the Recharging look, with its opacity, grey out, tint and glow."] = "충전이 하나 남은 채 다른 충전이 돌아오는 상태가 계속 반복됩니다. '충전 중' 모양과 그 투명도, 흑백, 색조, 반짝임이 적용됩니다."
L["A condition holds"] = "조건이 충족될 때"
L["A condition turns off"] = "조건이 꺼짐"
L["A condition turns on"] = "조건이 켜짐"
L["A cooldown ID names a Cooldown Manager icon, so it stays at its own spot."] = "재사용 대기시간 ID는 재사용 대기시간 관리자 아이콘을 가리키므로 자기 자리에 있습니다."
L["A cooldown ID names a Cooldown Manager icon."] = "재사용 대기시간 ID는 재사용 대기시간 관리자 아이콘을 가리킵니다."
L["A deck bar fills as the deck is drawn, with a mark for each proc."] = "덱 막대는 덱을 뽑을수록 채워지며, 발동마다 표시가 있습니다."
L["A deck of 100 stacks holding 2 Tempest procs."] = "폭풍 발동 2회가 들어 있는 중첩 100개짜리 덱입니다."
L["A deck of 250 stacks holding 5 Storm Unleashed procs."] = "폭풍 해방 발동 5회가 들어 있는 중첩 250개짜리 덱입니다."
L["A deck of 333 Maelstrom holding 2 Tempest procs."] = "폭풍 발동 2회가 들어 있는 소용돌이 333짜리 덱입니다."
L["A deck of 333 stacks holding 2 Ascendance procs."] = "승천 발동 2회가 들어 있는 중첩 333개짜리 덱입니다."
L["A deck of 600 Maelstrom Weapon stacks holding 3 Doom Winds procs."] = "파멸의 바람 발동 3회가 들어 있는 소용돌이치는 무기 중첩 600개짜리 덱입니다."
L["A dim dark line along the edge, under the moving lines."] = "움직이는 선 아래, 가장자리를 따라 흐리고 어두운 선을 그립니다."
L["A divider where each stage of an empowered cast begins, in the tick look. Shows with tick marks off too."] = "강화 주문의 각 단계가 시작되는 곳에 눈금 모양의 구분선을 표시합니다. 눈금 표시를 꺼도 보입니다."
L["A female voice"] = "여성 음성"
L["A fill, like a bar"] = "막대처럼 채우기"
L["A glow around the bar, with a trigger of its own. Works in combat."] = "막대 주위의 반짝임으로, 자체 트리거가 있습니다. 전투 중에도 작동합니다."
L["A grid of small tiles showing the art and the name. Click a tile to edit it. Hover it for its details, Edit and Delete."] = "아트와 이름을 보여 주는 작은 타일 격자입니다. 타일을 클릭하면 편집합니다. 마우스를 올리면 세부 정보, 편집, 삭제가 표시됩니다."
L["A group needs at least one column."] = "그룹에는 열이 하나 이상 필요합니다."
L["A group needs at least one row."] = "그룹에는 행이 하나 이상 필요합니다."
L["A layout for 1 class"] = "직업 1개용 구성"
L["A layout pack you use has a newer version."] = "사용 중인 구성 팩에 새 버전이 있습니다."
L["A longer line widens the window for as long as it shows."] = "더 긴 줄은 표시되는 동안 창을 넓힙니다."
L["A look of its own under a time left"] = "남은 시간 기준 이하에서 별도의 모양"
L["A look under a time left"] = "남은 시간 기준 이하의 모양"
L["A male voice"] = "남성 음성"
L["A mark where each spell's cost is met. It shows with Tick marks on (Appearance > Ticks)."] = "각 주문의 비용이 충족되는 지점에 표시합니다. 눈금 표시를 켜면 나타납니다 (외형 > 눈금)."
L["A mark where your next spell can be queued: press it past the mark and it goes off as soon as this cast ends."] = "다음 주문을 미리 입력할 수 있는 지점입니다. 이 표시를 지나서 누르면 현재 시전이 끝나자마자 시전됩니다."
L["A missing aura"] = "누락된 오라"
L["A name, version, link and notes for your pack. Whoever imports the string sees them first."] = "팩의 이름, 버전, 링크, 메모입니다. 문자열을 가져오는 사람이 가장 먼저 보게 됩니다."
L["A named frame"] = "이름 있는 프레임"
L["A nameplate: not offered"] = "이름표: 제공되지 않음"
L["A new rule: when something happens, what it does."] = "새 규칙: 어떤 일이 생기면 무엇을 할지 정합니다."
L["A newer version is out: click to update your copy"] = "새 버전이 나왔습니다. 클릭해 내 사본을 업데이트하십시오"
L["A newer version of this layout is out. Updates the layout you made from it; your own sizes and positions stay."] = "이 구성의 새 버전이 나왔습니다. 이를 바탕으로 만든 구성을 업데이트하며, 내가 정한 크기와 위치는 유지됩니다."
L["A percent of the bar, or power with In power units on."] = "막대의 퍼센트입니다. '자원 단위'를 켜면 자원 값입니다."
L["A picture of your own: its FileDataID, or its path such as Interface/AddOns/MyMedia/glow. Enter applies it; empty = pick one above."] = "직접 쓸 그림입니다. FileDataID 또는 Interface/AddOns/MyMedia/glow 같은 경로를 입력합니다. Enter를 누르면 적용되며, 비우면 위에서 고른 것을 씁니다."
L["A picture that follows an aura, a cooldown, your power, health or triggers."] = "오라, 재사용 대기시간, 자원, 생명력 또는 트리거를 따르는 그림입니다."
L["A power bar; Automatic follows the power you are using."] = "자원 막대입니다. 자동은 지금 사용 중인 자원을 따라갑니다."
L["A proc glow ended"] = "발동 반짝임 종료"
L["A proc glow started"] = "발동 반짝임 시작"
L["A proc shows it at full opacity"] = "발동 시 완전히 불투명하게 표시"
L["A quarter turn: the bar becomes tall and thin, and its icon, texture and gradient turn with it."] = "90도 회전: 막대가 길고 가늘어지며 아이콘, 텍스처, 그라데이션도 함께 회전합니다."
L["A reactive ability lit up"] = "반응형 능력 강조됨"
L["A reminder exported on its own joins this group. A group keeps one reminder per spell, item or weapon hand, so duplicates stay out."] = "단독으로 내보낸 알림은 이 그룹에 들어갑니다. 그룹은 주문, 아이템, 무기 슬롯마다 알림을 하나만 두므로 중복은 제외됩니다."
L["A returning icon"] = "다시 나타나는 아이콘"
L["A ring"] = "고리"
L["A ring of your spells and items: hold its key, point at one and let go to cast it."] = "주문과 아이템의 휠입니다. 단축키를 누른 채 하나를 가리키고 놓으면 사용합니다."
L["A ring, like a cooldown"] = "재사용 대기시간 같은 고리"
L["A set duration"] = "정해진 지속시간"
L["A share of the time"] = "시간 비율"
L["A short flash"] = "짧은 번쩍임"
L["A short word, like %s"] = "짧은 단어 (예: %s)"
L["A short word, like C"] = "짧은 단어 (예: C)"
L["A short word, like D"] = "짧은 단어 (예: D)"
L["A short word, like M"] = "짧은 단어 (예: M)"
L["A short word, like N"] = "짧은 단어 (예: N)"
L["A short word, like P"] = "짧은 단어 (예: P)"
L["A skin made from the default look. A bar's Skin dropdown makes one from that bar's look."] = "기본 모양으로 만든 스킨입니다. 막대의 스킨 드롭다운으로 해당 막대의 모양에서 스킨을 만들 수도 있습니다."
L["A soft glow around the icon in this type's color. Glow size is under All."] = "아이콘 주위에 이 유형의 색상으로 은은한 반짝임을 표시합니다. 반짝임 크기는 전체에 있습니다."
L["A sound"] = "소리"
L["A spare profile in Arc UI: its groups and icons come in switched off; turn them on in their Load tab."] = "Arc UI의 예비 프로필입니다. 그룹과 아이콘이 꺼진 채로 들어오며, 각자의 불러오기 탭에서 켤 수 있습니다."
L["A spark crosses the bar every 2 seconds and lands on each mana tick."] = "스파크가 2초마다 막대를 가로질러 마나 틱마다 도착합니다."
L["A spell"] = "주문"
L["A spell ID, a link, or the name of a spell you know."] = "주문 ID, 링크 또는 알고 있는 주문의 이름입니다."
L["A spell ID, a link, or the name of a spell you know. Any rank of it counts unless Only this rank is on."] = "주문 ID, 링크 또는 알고 있는 주문의 이름입니다. '이 등급만'을 켜지 않으면 모든 등급이 해당됩니다."
L["A spell ID, a link, or the name of a spell you know. Enter applies it."] = "주문 ID, 링크 또는 알고 있는 주문의 이름입니다. Enter를 누르면 적용됩니다."
L["A spell ID, a spell link, or the name of a spell in your spellbook: for spells the catalog does not list."] = "주문 ID, 주문 링크 또는 마법책에 있는 주문 이름입니다. 목록에 없는 주문에 사용합니다."
L["A spell ID, or the name of a spell you know. Any rank works: the bar follows the rank you know."] = "주문 ID 또는 알고 있는 주문의 이름입니다. 모든 등급이 가능하며, 막대는 배운 등급을 따릅니다."
L["A spell ID, or the name of a spell you know. It goes on the first empty spot; one you have not learned yet shows grey until you do."] = "주문 ID 또는 알고 있는 주문의 이름입니다. 첫 번째 빈 칸에 들어가며, 아직 배우지 않은 주문은 배울 때까지 회색으로 표시됩니다."
L["A spell ID, or the name of a spell you know. The rank you know is checked."] = "주문 ID 또는 알고 있는 주문의 이름입니다. 배운 등급으로 확인합니다."
L["A spell became usable"] = "주문 사용 가능해짐"
L["A spell is on cooldown"] = "주문 재사용 대기 중"
L["A spell is ready"] = "주문 준비됨"
L["A spell is recharging"] = "주문 충전 중"
L["A spell is usable"] = "주문 사용 가능"
L["A spell name or ID, such as Raptor Strike, Heroic Strike or Maul. Its marker shows where it comes off cooldown and while it is queued."] = "주문 이름 또는 ID입니다. 예: 랩터의 일격, 영웅의 일격, 후려갈기기. 표시선은 재사용 대기가 끝나는 지점과 예약된 동안을 나타냅니다."
L["A spell stopped being usable"] = "주문 사용 불가능해짐"
L["A spell's charges"] = "주문의 충전 횟수"
L["A spell's cooldown"] = "주문의 재사용 대기시간"
L["A spell's cooldown as an icon."] = "주문의 재사용 대기시간을 아이콘으로 표시합니다."
L["A spell's cooldown ended"] = "주문의 재사용 대기시간 종료"
L["A spell's cooldown started"] = "주문의 재사용 대기시간 시작"
L["A spell's custom text"] = "주문의 사용자 설정 텍스트"
L["A spend every half second, a proc at a third and two thirds of the deck, then a new deck."] = "0.5초마다 소모하고, 덱의 3분의 1과 3분의 2 지점에서 발동한 뒤, 새 덱이 시작됩니다."
L["A spot mid-screen where your cooldowns pulse as they come back."] = "재사용 대기시간이 돌아올 때 펄스가 표시되는 화면 중앙의 위치입니다."
L["A stance, form or aura from your stance bar. The icon lights up while you are in it."] = "태세 단축바의 태세, 변신 또는 오라입니다. 해당 상태인 동안 아이콘이 켜집니다."
L["A straight bar"] = "직선 막대"
L["A string to share this skin."] = "이 스킨을 공유하기 위한 문자열입니다."
L["A swipe over each icon while it is on cooldown."] = "재사용 대기 중인 아이콘마다 스와이프를 표시합니다."
L["A tick where each proc of this deck landed. A new deck clears them."] = "이 덱의 발동이 일어난 위치마다 눈금을 표시합니다. 새 덱이 시작되면 지워집니다."
L["A totem is gone"] = "토템 사라짐"
L["A totem or guardian in its slot, or one of them by the spell that puts it down."] = "슬롯에 있는 토템 또는 수호자이며, 이를 소환하는 주문으로 고른 하나일 수도 있습니다."
