L["A totem with 14 of its 24 seconds left, standing still."] = "24초 중 14초가 남은 채 멈춰 있는 토템입니다."
L["A trinket or other gear reminds you only while you wear it."] = "장신구나 다른 장비는 착용 중일 때만 알려줍니다."
L["A unit's health, with incoming heals and shields."] = "유닛의 생명력입니다. 들어오는 치유와 보호막도 표시합니다."
