L["Any lust on you: Bloodlust, Heroism, Time Warp, Primal Rage, Fury of the Aspects, Harrier's Cry and the drums, on one icon."] = "내게 걸린 모든 영웅심 계열 효과: 피의 욕망, 영웅심, 시간 왜곡, 원초적 분노, 위상의 격노, 유린자의 울음소리 및 북 효과를 아이콘 하나에 표시합니다."
L["Any of %d items: the icon shows the best one you carry and can use."] = "아이템 %d개 중 하나: 가지고 있고 사용할 수 있는 가장 좋은 것을 보여 줍니다."
