L["Any rank: whichever rank you queue. Highest rank: only your best one. A rank: only that one, like a cheaper rank queued to save mana."] = "모든 등급: 예약한 등급을 따릅니다. 가장 높은 등급: 가장 좋은 등급만 해당합니다. 하나의 등급: 그 등급만 해당합니다. 예를 들어 마나를 아끼려고 예약하는 더 저렴한 등급입니다."
L["Any shaman imbue, every rank"] = "모든 주술사 무기 강화, 모든 등급"
