L["Anyone lacks it: a buff the whole group needs. Nobody has it: a buff kept on one member, like Beacon of Light or Earth Shield."] = "누군가에게 없음: 파티 전원에게 필요한 강화 효과입니다. 아무도 없음: 빛의 봉화나 대지의 보호막처럼 한 명에게 유지하는 강화 효과입니다."
L["Anyone, only yours (or your pet's), or only other players' copies of the aura."] = "누구나, 내 것(또는 내 소환수의 것)만, 또는 다른 플레이어의 오라만 해당합니다."
L["Anyone: any copy counts. Me: only yours, so your Beacon or Earth Shield, not another player's."] = "누구나: 누구의 것이든 인정됩니다. 나: 내 것만 해당하므로 내 빛의 봉화나 대지의 보호막이며, 다른 플레이어의 것은 제외됩니다."
L["Anyone: any copy fills the bar. Me: only yours or your pet's. Anyone but me: only copies from other players."] = "누구나: 오라의 어떤 사본이든 막대를 채웁니다. 나: 내 것 또는 내 소환수의 것만 봅니다. 나를 제외한 누구나: 다른 플레이어가 건 사본만 봅니다."
L["Anyone: any copy lights the icon. Me: only yours or your pet's. Anyone but me: only copies from other players."] = "누구나: 오라의 어떤 사본이든 아이콘을 밝힙니다. 나: 내 것 또는 내 소환수의 것만 봅니다. 나를 제외한 누구나: 다른 플레이어가 건 사본만 봅니다."
