L["Copies one of your macros into the box below as a start. It never takes that macro over."] = "아래 입력란에 내 매크로 하나를 시작용으로 복사합니다. 해당 매크로를 넘겨받지는 않습니다."
L["Copies the layout's class and talent checks to those items so they load where the layout does. Load When rules stay."] = "구성의 직업, 특성 확인을 해당 아이템들에 복사해 구성이 불러와지는 곳에서 함께 불러옵니다. 불러올 조건 규칙은 유지됩니다."
L["Copies the layout's class, spec and talent checks to those items so they load where the layout does. Load When rules stay."] = "구성의 직업, 전문화, 특성 확인을 해당 아이템들에 복사해 구성이 불러와지는 곳에서 함께 불러옵니다. 불러올 조건 규칙은 유지됩니다."
L["Copies the rows of this sub-panel onto the chosen target. Copy semantics - no live link; the target keeps its own values from then on."] = "이 하위 패널의 행을 선택한 대상에 복사합니다. 복사일 뿐 연결되지 않으며, 이후 대상은 자체 값을 유지합니다."
L["Copies the selection to the picked place and leaves the originals. Each copy keeps its settings, name and position."] = "선택한 항목을 고른 곳에 복사하고 원본은 그대로 둡니다. 각 사본은 설정, 이름, 위치를 유지합니다."
L["Copies this group's class and spec checks onto those icons, so they load wherever the group does."] = "이 그룹의 직업 및 전문화 확인을 해당 아이콘들에 복사해, 그룹이 불러와지는 곳에서는 아이콘도 불러와집니다."
