L["Each icon shows only while its buff is missing, in combat too."] = "각 아이콘은 강화 효과가 없을 때만 표시되며, 전투 중에도 마찬가지입니다."
L["Each icon's Text > Custom Text & Keybind sets the text's size, color and position."] = "각 아이콘의 텍스트 > 사용자 설정 텍스트 및 단축키에서 텍스트 크기, 색상, 위치를 정합니다."
L["Each number in the custom list wears its own colour, in the order you typed them; the Tick color is the first."] = "사용자 목록의 각 숫자는 입력한 순서대로 각자의 색상을 씁니다. 첫 번째 색은 눈금 색상입니다."
L["Each power (druid forms)"] = "자원별 (드루이드 변신)"
