L["Emity's latest version: Dark Inspiration, anchors for more player frames, and stack counts from 1."] = "Emity의 최신 버전: Dark Inspiration, 더 많은 플레이어 프레임용 고정점, 1중첩부터 표시되는 중첩 수."
L["Emity's latest version: Incinerate, Conflagrate and Soul Fire, Demon Skin in Missing Buffs, anchors for more player frames, and stack counts from 1."] = "Emity의 최신 버전: 소각, 점화, 영혼의 불꽃, 누락된 버프의 악마의 피부, 더 많은 플레이어 프레임용 고정점, 1중첩부터 표시되는 중첩 수."
L["Emity's latest version: Maelstrom Weapon and mana bars for Enhancement, Elemental Mastery, anchors for more player frames, and stack counts from 1."] = "Emity의 최신 버전: 고양 전문화용 소용돌이치는 무기와 마나 바, 정기의 숙련, 더 많은 플레이어 프레임용 고정점, 1중첩부터 표시되는 중첩 수."
L["Emity's latest version: Reckoning, the new Vindication, Blessing of Freedom, anchors for more player frames, and stack counts from 1."] = "Emity의 최신 버전: 징벌, 새 응징, 자유의 축복, 더 많은 플레이어 프레임용 고정점, 1중첩부터 표시되는 중첩 수."
L["Emity's latest version: Revenge and Overpower icons that light up when you can use them."] = "Emity의 최신 버전: 복수와 제압을 사용할 수 있을 때 빛나는 아이콘."
L["Emity's latest version: Scorpid Sting, Scatter Shot and Expose Prey on your target, both hawks, your off-hand enchant, anchors for more player frames, and stack counts from 1."] = "Emity의 최신 버전: 대상의 전갈 쐐기, 산탄 사격, Expose Prey, 매 두 마리, 보조장비 마법부여, 더 많은 플레이어 프레임용 고정점, 1중첩부터 표시되는 중첩 수."
L["Emity's latest version: a Thousand Cuts bar for Subtlety, anchors for more player frames, and stack counts from 1."] = "Emity의 최신 버전: 잠행 전문화용 Thousand Cuts 바, 더 많은 플레이어 프레임용 고정점, 1중첩부터 표시되는 중첩 수."
L["Emity's latest version: bars for Arcane Blast, Heating Up and Fingers of Frost, Arcane Wrath, anchors for more player frames, and stack counts from 1."] = "Emity의 최신 버전: 비전 작렬, 열기, 서리의 손가락 바, Arcane Wrath, 더 많은 플레이어 프레임용 고정점, 1중첩부터 표시되는 중첩 수."
L["Emity's latest version: missing buff reminders show only for spells you know."] = "Emity의 최신 버전: 누락된 버프 알림이 알고 있는 주문에만 표시됩니다."
