L["Finds the spells and items on your action bars and lets you pick which become icons in this group. Out of combat only."] = "행동 단축바에 있는 주문과 아이템을 찾아, 이 그룹에서 아이콘으로 만들 항목을 고르게 해 줍니다. 비전투 중에만 가능합니다."
L["Fine tune"] = "세부 조정"
L["Fine-tuning for the rows above. Click to show or hide it."] = "위 항목의 세부 조정입니다. 클릭하면 보이거나 숨깁니다."
L["Fine-tuning for the rows above; some differ from their default. Click to show or hide it."] = "위 항목의 세부 조정이며, 일부는 기본값과 다릅니다. 클릭하면 보이거나 숨깁니다."
L["Fine-tuning for this one. Click to show or hide it."] = "이 항목의 세부 조정입니다. 클릭하면 표시하거나 숨깁니다."
