L["Fires as soon as the spell's own requirement is met (a proc, enough mana), even while it is on cooldown."] = "주문 자체의 조건(발동, 충분한 마나)이 충족되는 즉시 실행되며, 재사용 대기 중이어도 실행됩니다."
L["Fires each time the game updates this spell's cooldown, and for some buffs as they come and go."] = "게임이 이 주문의 재사용 대기시간을 갱신할 때마다, 그리고 일부 강화 효과가 생기거나 사라질 때 실행됩니다."
L["Fires only while the spell's proc glow is up, on top of the trigger's own timing. An item checks its use spell."] = "트리거 자체의 시점에 더해, 주문의 발동 반짝임이 켜져 있는 동안에만 실행됩니다. 아이템은 사용 효과 주문을 확인합니다."
L["Fires the first trigger once, as it will in play, even where the conditions would keep it quiet."] = "조건 때문에 실행되지 않을 상황에서도, 실제 플레이처럼 첫 번째 트리거를 한 번 실행합니다."
