L["Hides between casts; shows a sample cast while this window is open."] = "시전 사이에는 숨겨지고, 이 창이 열려 있는 동안 예시 시전을 표시합니다."
L["Hides casts you cannot interrupt. In combat the game hides that from addons, so it cannot drive sounds or alerts."] = "차단할 수 없는 시전을 숨깁니다. 전투 중에는 게임이 이를 애드온에게 숨기므로 소리나 경보에는 쓸 수 없습니다."
L["Hides it on screen while this window is open, so you can get at what sits under it. Closing the window shows it again."] = "이 창이 열려 있는 동안 화면에서 숨겨, 아래에 있는 것을 만질 수 있게 합니다. 창을 닫으면 다시 표시됩니다."
L["Hides the game's castbar under your character while this castbar is loaded. Turn off to bring it back on your next cast."] = "이 시전바를 불러온 동안 캐릭터 아래의 게임 시전바를 숨깁니다. 끄면 다음 시전부터 돌아옵니다."
L["Hides the minimap button. %s always opens this window. Drag the button along the rim to move it, right-click for move mode."] = "미니맵 버튼을 숨깁니다. %s 명령은 항상 이 창을 엽니다. 버튼을 테두리를 따라 끌어 옮기고, 오른쪽 클릭으로 이동 모드를 전환합니다."
L["Hides this update here until the next version. The tag on the layout in the sidebar stays."] = "다음 버전까지 이 업데이트 알림을 여기서 숨깁니다. 사이드바의 구성에 붙은 표시는 그대로 남습니다."
L["Hides while the unit is not there; always shows while this window is open."] = "유닛이 없으면 숨기고, 이 창이 열려 있는 동안에는 항상 표시합니다."
