L["Highlight icons when you press their button"] = "버튼을 누르면 아이콘 강조"
L["Highlight lasts"] = "강조 지속시간"
L["Highlight opacity"] = "강조 투명도"
L["Hold %s over any bound spell to ping it."] = "%s 키를 누른 채 키가 지정된 주문의 키를 누르면 핑을 보냅니다."
L["Hold %s over any bound spell to ping it. %d of %d picked spells ping their own way."] = "%s 키를 누른 채 키가 지정된 주문의 키를 누르면 핑을 보냅니다. 선택한 주문 중 %d / %d개는 각자의 방식으로 핑을 보냅니다."
L["Hold %s, then press %s."] = "%s 키를 누른 채 %s 키를 누르십시오."
L["Hold for (s)"] = "유지 시간 (초)"
L["Hold interrupted and failed casts"] = "차단되거나 실패한 시전 유지"
L["Hold the ping key and press a spell's own key to ping it instead of casting it. Nothing is rebound while this is off."] = "핑 단축키를 누른 채 주문의 단축키를 누르면 시전하는 대신 핑을 보냅니다. 꺼져 있으면 아무것도 재지정되지 않습니다."
L["Hold this and press a spell's key to ping the spell. Click, then press a key; right-click clears it."] = "이 키를 누른 채 주문의 키를 누르면 그 주문의 핑을 보냅니다. 클릭한 뒤 키를 누르십시오. 오른쪽 클릭으로 지웁니다."
L["Hold this instead of the main ping key to ping this spell. Not set uses the main ping key. Right-click clears it."] = "기본 핑 단축키 대신 이 키를 누르면 이 주문의 핑을 보냅니다. 지정하지 않으면 기본 핑 단축키를 사용합니다. 오른쪽 클릭으로 지웁니다."
L["Hold: its key still casts, and holding the ping key pings instead. Every press: casts and pings. Its own key: pings and casts nothing."] = "누르고 있기: 주문 키는 그대로 시전하고, 핑 단축키를 누르고 있으면 대신 핑을 보냅니다. 누를 때마다: 시전하고 핑도 보냅니다. 전용 키: 핑만 보내고 시전하지 않습니다."
