L["Hot from (%)"] = "높은 확률 기준 (%)"
L["Hover a game frame on screen and click it. Right-click or Esc cancels."] = "화면의 게임 프레임 위에 마우스를 올리고 클릭하십시오. 오른쪽 클릭이나 Esc로 취소합니다."
L["Hover a game frame or one of your Arc Auras items and click it. On an icon in a group, Shift-click takes the icon."] = "게임 프레임이나 Arc Auras 항목 위에 커서를 올리고 클릭하십시오. 그룹 안의 아이콘에서는 Shift-클릭하면 그 아이콘을 고릅니다."
L["Hover a game frame, an action button, a Cooldown Manager icon or an Arc Auras icon and left-click it. Right-click or Esc cancels."] = "게임 프레임, 행동 버튼, 재사용 대기시간 관리자 아이콘 또는 Arc Auras 아이콘 위에 마우스를 올리고 왼쪽 클릭하십시오. 오른쪽 클릭이나 Esc로 취소합니다."
L["Hovering an icon shows its spell, item or totem tooltip."] = "아이콘 위에 마우스를 올리면 주문, 아이템, 토템 툴팁을 표시합니다."
L["How big the preview is against the bar's real size. Click to fit the whole bar in view again."] = "미리 보기가 막대 실제 크기의 몇 배인지 나타냅니다. 클릭하면 막대 전체가 다시 한눈에 보이도록 맞춥니다."
L["How countdown numbers round. Up: 13.2 reads 14, like action bar cooldowns. Down: 13.2 reads 13, like buff timers and nameplates."] = "초읽기 숫자를 반올림하는 방식입니다. 올림: 13.2를 14로 표시하며 행동 단축바 재사용 대기시간과 같습니다. 내림: 13.2를 13으로 표시하며 강화 효과 타이머와 이름표와 같습니다."
L["How far the glow reaches past the icon: 1 sits on its edge."] = "반짝임이 아이콘 밖으로 뻗는 정도입니다. 1이면 가장자리에 놓입니다."
L["How far your target is, in colored range bands you can edit."] = "대상까지의 거리를 편집할 수 있는 색상 사정거리 구간으로 표시합니다."
L["How fast a line is spoken. 0 follows WoW's own speech rate."] = "한 문장을 읽는 속도입니다. 0이면 WoW 자체 음성 속도를 따릅니다."
L["How it looks in each state"] = "각 상태의 모양"
L["How it shows"] = "표시 방식"
L["How long a flash shows. A held button keeps the highlight at least this long, so clicks that cast on release still show."] = "번쩍임이 표시되는 시간입니다. 버튼을 누르고 있으면 강조 효과가 최소 이 시간 동안 유지되므로, 손을 뗄 때 시전되는 클릭도 표시됩니다."
L["How long after that rule last fired this one may fire (Not after: may not fire). Enter applies it."] = "그 규칙이 마지막으로 실행된 뒤 이 규칙이 실행될 수 있는 시간입니다 ('이후 아님'은 실행되지 않음). Enter를 누르면 적용됩니다."
L["How long after your cast it may land and still light this in combat. One that flies in first needs longer (Summon Hawk: 1.5 s)."] = "시전 후 얼마나 늦게 나타나도 전투 중 이것을 켜는지입니다. 먼저 날아가는 것은 더 깁니다 (Summon Hawk: 1.5초)."
L["How long it shows after each cast."] = "시전할 때마다 표시되는 시간입니다."
L["How long the bar takes to fade away when a cast ends (after the hold, when that is on). 0 = it goes at once."] = "시전이 끝난 뒤 막대가 사라지는 데 걸리는 시간입니다(유지가 켜져 있으면 유지가 끝난 뒤). 0이면 바로 사라집니다."
L["How long the button glow takes to fade when it stops. 0: it goes at once."] = "버튼 반짝임이 멈출 때 사라지는 데 걸리는 시간입니다. 0이면 바로 사라집니다."
L["How long the timer runs when a rule starts it with no seconds of its own. Enter applies it."] = "규칙이 자체 초 없이 타이머를 시작할 때 타이머가 진행되는 시간입니다. Enter를 누르면 적용됩니다."
L["How long the timer runs, and each stack when stacks run out on their own, when a rule gives no seconds. Enter applies it."] = "규칙에 초가 없을 때 타이머가 도는 시간이며, 중첩이 각자 만료될 때는 각 중첩의 시간입니다. Enter로 적용합니다."
L["How long the timer runs, or an added stack lasts; 0 takes the item's Default seconds. Decimals work (1.5). Enter applies it."] = "타이머가 진행되는 시간 또는 추가된 중첩이 유지되는 시간입니다. 0이면 아이템의 기본 초를 따릅니다. 소수도 가능합니다 (1.5). Enter를 누르면 적용됩니다."
L["How long, in seconds; decimals work (1.5). Enter applies it."] = "시간(초)입니다. 소수도 가능합니다 (1.5). Enter를 누르면 적용됩니다."
L["How many"] = "개수"
L["How many charges are up; Blank at zero below hides the 0."] = "사용 가능한 충전 횟수입니다. 아래의 '0일 때 비움'은 0을 숨깁니다."
L["How many in your party or raid have a buff."] = "파티나 공격대에서 강화 효과를 가진 인원 수입니다."
L["How many nameplates get a row, in the order the game numbers them. Each one keeps a set of frames ready."] = "몇 개의 이름표에 행을 줄지 정합니다. 게임이 매기는 번호 순서이며, 각 이름표는 프레임 세트를 준비해 둡니다."
L["How many rows of auras show, each Columns wide; up to 40 auras. The rest show as others end."] = "표시할 오라 행 수이며, 각 행은 열 수만큼 넓습니다. 최대 40개까지 표시하고, 나머지는 다른 오라가 끝나면 표시됩니다."
L["How many stacks the next spender eats; the chance is for that many draws."] = "다음 소모 주문이 소모하는 중첩 수입니다. 확률은 그 횟수만큼 뽑을 때의 확률입니다."
L["How many stage colors to list and show while editing; set it to your spell's stages."] = "목록과 편집 미리보기에 보여줄 단계 색상 수입니다. 주문의 단계 수에 맞추세요."
L["How many you carry, on items that stack, such as potions."] = "물약처럼 겹쳐지는 아이템의 보유 개수입니다."
L["How the bar looks in each state"] = "각 상태의 막대 모양"
L["How visible the icon is %s."] = "%s 아이콘이 보이는 정도입니다."
L["How visible the icon is on cooldown until On cooldown's opacity starts."] = "'대기 중' 투명도가 시작되기 전까지, 재사용 대기 중인 아이콘이 보이는 정도입니다."
L["How visible the icon is until this opacity starts. 0 hides it."] = "이 투명도가 시작되기 전까지 아이콘이 얼마나 보이는지 정합니다. 0이면 숨깁니다."
L["How visible the icon is while the aura is up, until Active's opacity starts."] = "'활성' 투명도가 시작되기 전까지, 오라가 있는 동안 아이콘이 보이는 정도입니다."
L["How visible the icon is while this look shows. 0 hides it."] = "이 모양이 적용되는 동안 아이콘이 보이는 정도입니다. 0이면 숨깁니다."
L["However many pings arrive, the sound plays at most once in this time."] = "핑이 아무리 많이 와도 이 시간 안에는 소리가 최대 한 번만 재생됩니다."
