L["Icons in this state give up their spot too, and take one again when it ends."] = "이 상태의 아이콘도 자리를 내주고, 상태가 끝나면 다시 자리를 차지합니다."
L["Icons of an ability flash when you press its button, cast it by macro or use the trinket. All ranks count as one."] = "행동 버튼을 누르거나 매크로로 시전하거나 장신구를 사용하면 그 능력의 아이콘이 잠깐 밝아집니다. 모든 등급을 같은 능력으로 셉니다."
