L["Icons that use this group's size keep their picture's shape: its edges are cropped, never stretched."] = "이 그룹의 크기를 쓰는 아이콘은 그림의 비율을 유지합니다. 가장자리를 잘라 내며, 늘이지 않습니다."
L["Icons with no shape of their own take this one."] = "자체 형태가 없는 아이콘은 이 형태를 씁니다."
L["Icons, bars, texts and the gaps between them grow together."] = "아이콘, 막대, 텍스트와 그 사이의 간격이 함께 커집니다."
