L["In combat the game hides buffs, so the count stops; this shows the icon, without a count, while it reminds, drawn by the game."] = "전투 중에는 게임이 강화 효과를 숨기므로 개수가 멈춥니다. 알림 중에는 게임이 그리는 아이콘을 개수 없이 표시합니다."
