L["It keeps its spot in its Dynamic group."] = "동적 그룹 안에서 자기 자리를 유지합니다."
L["It lasts (seconds)"] = "지속 (초)"
L["It pulses when its cooldown is back; add more triggers after."] = "재사용 대기시간이 돌아오면 펄스가 나타납니다. 이후 트리거를 더 추가할 수 있습니다."
L["It pulses when the enchant is missing; add more triggers after."] = "마법부여가 없으면 펄스가 나타납니다. 이후 트리거를 더 추가할 수 있습니다."
L["It shows beside the pulse while the aura is missing, in combat too."] = "오라가 없는 동안 펄스 옆에 표시되며, 전투 중에도 마찬가지입니다."
L["It sits by the group and moves with it."] = "그룹 옆에 놓이며 그룹과 함께 움직입니다."
L["It sits on the first one that is on screen, top to bottom."] = "화면에 있는 첫 번째 것에 붙습니다(위에서 아래 순서)."
L["It starts as this state's look. When several hold, the top one wins."] = "처음에는 이 상태의 모양과 같습니다. 여러 개가 해당하면 맨 위의 것이 적용됩니다."
L["It starts out of combat, or after a /reload."] = "비전투 상태이거나 /reload 후에 시작합니다."
L["It wears the spell whose cast started its timer: one Fire Trap icon for whichever fire trap you laid."] = "타이머를 시작한 시전 주문의 모양을 씁니다. 어떤 화염 덫을 놓든 화염 덫 아이콘 하나로 표시됩니다."
