L["Items in the string that you do not have yet come in, where it puts them."] = "문자열에 있고 아직 내게 없는 아이템은 문자열이 지정한 위치로 들어옵니다."
L["Items that came from this pack but are no longer in the string go. Anything you added yourself always stays."] = "이 팩에서 왔지만 문자열에 더 이상 없는 아이템은 제거됩니다. 직접 추가한 항목은 항상 유지됩니다."
L["Items you deleted"] = "삭제한 아이템"
L["Its Dynamic group hides it on cooldown."] = "동적 그룹이 재사용 대기 중에는 숨깁니다."
L["Its Masque skin draws the border and the shadow."] = "Masque 스킨이 테두리와 그림자를 그립니다."
L["Its Masque skin sets the picture's size, crop and shape."] = "Masque 스킨이 그림의 크기, 자르기, 형태를 정합니다."
L["Its auras come after those of the type now on its right."] = "이 유형의 오라는 지금 오른쪽에 있는 유형의 오라 뒤에 옵니다."
L["Its auras come before those of the type now on its left."] = "이 유형의 오라는 지금 왼쪽에 있는 유형의 오라 앞에 옵니다."
L["Its bars become a new layout of groups: same spells, sizes and places. Then it turns off."] = "막대가 그룹으로 이루어진 새 구성으로 바뀝니다: 같은 주문, 크기, 위치입니다. 이후 꺼집니다."
L["Its buff"] = "해당 강화 효과"
L["Its group orders by Time left, so in play it wears a new aura icon's look."] = "그룹이 남은 시간 순으로 정렬되므로, 플레이 중에는 새 오라 아이콘의 모양을 씁니다."
L["Its group turns this look on: the group's Appearance > Icons."] = "그룹이 이 모양을 켭니다: 그룹의 외형 > 아이콘."
L["Its groups come from Arc UI's shared layout '%s'."] = "그룹은 Arc UI의 공유 구성 '%s'에서 가져옵니다."
L["Its layout is locked, so it stays put anyway."] = "구성이 잠겨 있으므로 어차피 그대로 있습니다."
L["Its look"] = "모양"
L["Its opacity replaces the state's"] = "이 투명도가 상태의 투명도를 대체"
L["Its own icon"] = "자체 아이콘"
L["Its own key, ping only"] = "전용 키, 핑만"
L["Its own spot"] = "자기 자리"
L["Its own spot, or riding another frame: it follows that frame and goes back to its own spot while the frame is not on screen."] = "자기 자리 또는 다른 프레임에 얹히기: 그 프레임을 따라가며, 프레임이 화면에 없는 동안에는 자기 자리로 돌아갑니다."
L["Its point"] = "프레임의 지점"
L["Its reminders and their pulse, sound and glow."] = "알림과 그 펄스, 소리, 반짝임."
L["Its rules (the Triggers tab) start its timer and count its stacks from events you pick."] = "규칙(트리거 탭)이 고른 이벤트로 타이머를 시작하고 중첩을 셉니다."
L["Its rules are below."] = "규칙은 아래에 있습니다."
L["Its rules are on the Triggers tab: they start its timer and count its stacks."] = "규칙은 트리거 탭에 있으며, 타이머를 시작하고 중첩을 셉니다."
L["Its rules go on the Triggers tab once it is made."] = "만든 뒤에는 규칙을 트리거 탭에서 설정합니다."
L["Its rules on the Triggers tab start its timer and count its stacks."] = "트리거 탭의 규칙이 타이머를 시작하고 중첩을 셉니다."
L["Its stack options. Click to show or hide them."] = "중첩 설정입니다. 클릭하면 표시하거나 숨깁니다."
L["Its totem"] = "해당 토템"
L["Its totem or an aura"] = "해당 토템 또는 오라"
L["Its triggers are on the Triggers tab: they decide when the picture shows, and a fill runs with their timer."] = "트리거는 트리거 탭에 있으며, 그림이 표시되는 시점을 정하고 채우기는 트리거의 타이머에 맞춰 진행됩니다."
L["Joins the end"] = "끝에 합류"
L["Jumps to where the swing lands"] = "스윙이 들어가는 지점으로 이동"
