L["Keep this texture under Favorites."] = "이 텍스처를 즐겨찾기에 보관합니다."
L["Keep typing: at least 3 letters of the name"] = "계속 입력하십시오: 이름 최소 3글자"
L["Keeps + and the eye on every sidebar row. Off: they show when the row is under the mouse, so names get more room."] = "모든 사이드바 행에 +와 눈 아이콘을 항상 표시합니다. 끄면 마우스를 올린 행에만 표시되어 이름 공간이 넓어집니다."
L["Keeps a mashed key from flooding the group. It counts presses, not time, and the cast always goes through."] = "키를 연타해도 그룹에 핑이 쏟아지지 않게 합니다. 시간이 아니라 누른 횟수를 세며, 시전은 항상 이루어집니다."
