L["Leaves out what does not load on this character. Those items stay listed, grayed, under each layout's NOT LOADED."] = "이 캐릭터에서 불러오지 않는 항목을 제외합니다. 제외된 항목은 각 구성의 '불러오지 않음' 아래에 흐리게 계속 표시됩니다."
L["Leaves the items you have alone and brings a second copy in."] = "이미 있는 아이템은 그대로 두고 사본을 하나 더 가져옵니다."
