L["Lights for any enchant on the weapon: an imbue, a poison, an oil or a stone."] = "무기의 모든 마법부여(무기 강화, 독, 오일, 숫돌)에 밝아집니다."
L["Lights the moment you cast, timed from the cast, until it lands in its slot. Needs one cast out of combat to learn its time."] = "시전하는 순간 켜지고, 칸에 들어올 때까지 시전부터 시간을 잽니다. 지속시간을 알려면 전투 밖에서 한 번 시전해야 합니다."
L["Lights up an icon the moment you press its button, cast it from a macro or use a trinket."] = "버튼을 누르거나, 매크로로 시전하거나, 장신구를 사용하는 순간 아이콘이 밝아집니다."
L["Line length (0 = auto)"] = "줄 길이 (0 = 자동)"
