L["Lists every item the update changes, adds or drops, with a Keep mine tick on each changed one."] = "업데이트가 바꾸거나 추가하거나 제거하는 모든 아이템을 나열하며, 변경되는 항목마다 '내 것 유지' 체크가 있습니다."
L["Lit while an enchant is on the weapon: an imbue, a poison, an oil or a stone."] = "무기에 마법부여가 있는 동안 켜집니다: 무기 강화, 독, 오일, 숫돌."
L["Live rows show buffs on you or your pet and debuffs on your target."] = "실시간 행은 나나 소환수의 강화 효과와 대상의 약화 효과를 표시합니다."
