L["Loads only once you know %s."] = "%s 습득 후에만 불러옵니다."
L["Loads only once you know %s. Known now."] = "%s 습득 후에만 불러옵니다. 현재 알고 있음."
L["Loads only once you know %s. Not known now."] = "%s 습득 후에만 불러옵니다. 현재 알지 못함."
L["Loads only while EVERY checked condition is true. Unloaded, it is fully gone, and returns when that changes, in combat too."] = "체크한 모든 조건이 참인 동안에만 불러옵니다. 불러오지 않으면 완전히 사라지며, 조건이 바뀌면 전투 중에도 다시 나타납니다."
L["Loads only while EVERY checked condition is true. Unloaded, it is hidden and returns when that changes. Aura sounds still play."] = "체크한 모든 조건이 참인 동안에만 불러옵니다. 불러오지 않으면 숨겨지고, 조건이 바뀌면 다시 나타납니다. 오라 소리는 계속 재생됩니다."
L["Loads only while at least one checked condition is true. Unloaded, it is fully gone, and returns when that changes, in combat too."] = "체크한 조건 중 하나 이상이 참인 동안에만 불러옵니다. 불러오지 않으면 완전히 사라지며, 조건이 바뀌면 전투 중에도 다시 나타납니다."
L["Loads only while at least one checked condition is true. Unloaded, it is hidden and returns when that changes. Aura sounds still play."] = "체크한 조건 중 하나 이상이 참인 동안에만 불러옵니다. 불러오지 않으면 숨겨지고, 조건이 바뀌면 다시 나타납니다. 오라 소리는 계속 재생됩니다."
