L["Off: every %s loads them, each by its own specs and talents. Cast bars always stay on %s."] = "끔: %s 전체에서 불러오며, 각각 자체 전문화와 특성에 따릅니다. 시전바는 항상 %s에서만 유지됩니다."
L["Off: no ready check picker, group message or interrupt alert in this spec. Your macros still update."] = "꺼짐: 이 전문화에서는 전투 준비 선택창, 그룹 메시지, 차단 경보가 나오지 않습니다. 매크로는 계속 갱신됩니다."
L["Off: silent while you are in a party."] = "끔: 파티 중에는 소리를 내지 않습니다."
L["Off: silent while you are in a raid group."] = "끔: 공격대 중에는 소리를 내지 않습니다."
L["Off: silent while you are not in a group."] = "끔: 그룹에 속하지 않았을 때는 소리를 내지 않습니다."
L["Off: the bar shows its no-band look while the target is in this band."] = "끄면 대상이 이 구간에 있는 동안 막대가 구간 없음 모양으로 표시됩니다."
L["Off: this trigger plays its sound or speech only, with no pulse."] = "끄면 이 트리거는 펄스 없이 소리나 음성만 재생합니다."
L["Off: this trigger pulses silently. A new trigger starts silent."] = "끄면 이 트리거는 소리 없이 펄스만 합니다. 새 트리거는 소리 없이 시작합니다."
L["Offset X"] = "X 오프셋"
L["Offset Y"] = "Y 오프셋"
L["On %s."] = "%s에 있음."
L["On a nameplate the bar hides while this window is open; the preview shows it."] = "이름표에 붙은 막대는 이 창이 열려 있는 동안 숨겨지며, 미리 보기에서 볼 수 있습니다."
L["On a ready check"] = "전투 준비 시"
L["On anchor %d, %s."] = "기준점 %d, %s."
L["On cooldown"] = "대기 중"
L["On cooldown alpha"] = "대기 중 투명도"
L["On cooldown opacity starts near the end"] = "끝 무렵에 대기 중 투명도 적용"
L["On cooldown starts with this many seconds left"] = "남은 시간이 이 초 이하일 때 대기 중 적용"
L["On cooldown too"] = "재사용 대기 중에도"
L["On cooldown's opacity waits until little time is left; before that the icon takes Before that's opacity."] = "'대기 중' 투명도는 남은 시간이 얼마 없을 때 적용됩니다. 그 전에는 아이콘이 '그 전' 투명도를 따릅니다."
L["On it now: %s."] = "지금 걸려 있음: %s."
L["On proc"] = "발동 시"
L["On proc (proc glow turns on)"] = "발동 시 (발동 반짝임 켜짐)"
L["On ranked realms, follow whichever rank of this spell you know now."] = "등급이 있는 서버에서는 지금 알고 있는 이 주문의 등급을 따릅니다."
L["On ranked realms, read whichever rank of this spell you know now."] = "등급이 있는 서버에서는 지금 알고 있는 이 주문의 등급을 읽습니다."
L["On ranked realms, track whichever rank of this spell you currently know. Re-resolves on spell changes."] = "등급이 있는 서버에서는 지금 알고 있는 이 주문의 등급을 추적합니다. 주문이 바뀌면 다시 확인합니다."
L["On screen"] = "화면에"
L["On the Cooldown Manager icon for %s."] = "%s의 재사용 대기시간 관리자 아이콘에 있습니다."
L["On the Cooldown Manager icon of %s."] = "%s의 재사용 대기시간 관리자 아이콘에 있습니다."
L["On the Cooldown Manager icon with cooldown ID %s."] = "재사용 대기시간 ID %s인 재사용 대기시간 관리자 아이콘에 있습니다."
L["On the action button holding %s (%s)."] = "%s|1이;가; 있는 행동 버튼에 있습니다 (%s)."
L["On the action button holding %s."] = "%s|1이;가; 있는 행동 버튼에 있습니다."
L["On the action button with %s."] = "%s|1이;가; 있는 행동 버튼에 있습니다."
L["On the bar"] = "막대 위에"
L["On the group"] = "그룹에"
L["On the icon"] = "아이콘 위"
L["On the icon with cooldown ID %s."] = "재사용 대기시간 ID %s인 아이콘에 있습니다."
L["On this icon"] = "이 아이콘에"
L["On top"] = "맨 위"
L["On unit"] = "유닛"
L["On use (when cast)"] = "사용 시 (시전할 때)"
L["On your screen"] = "내 화면에"
L["On: adding stacks also starts the timer over, with the seconds below."] = "켬: 중첩을 추가하면 타이머도 아래의 초로 다시 시작합니다."
L["On: every Arc Proc resets the moment a key starts, so a reset is never missed. Off: on the gate drop, which keeps the skip working."] = "켜면 쐐기돌이 시작되는 순간 모든 Arc 발동이 초기화되어 초기화를 놓치지 않습니다. 끄면 관문이 열릴 때 초기화되어 건너뛰기가 계속 작동합니다."
L["On: icons pack (Show while missing ones too). Off: every aura keeps its spot."] = "켜면 아이콘이 모입니다('없을 때 표시' 아이콘 포함). 끄면 모든 오라가 자리를 유지합니다."
L["On: it glows while this look shows. Click to switch it."] = "켜짐: 이 모양이 적용되는 동안 반짝입니다. 클릭하면 전환됩니다."
L["On: the debuffs start on the line after the buffs. Off: they follow straight on."] = "켜면 약화 효과가 강화 효과 다음 줄에서 시작합니다. 끄면 바로 이어집니다."
L["On: the rule fires only while the conditions below hold. Off drops them."] = "켬: 아래 조건이 충족되는 동안에만 규칙이 실행됩니다. 끄면 조건이 해제됩니다."
L["On: the skin sets it for every bar that wears it. Off: each bar keeps its own."] = "켬: 스킨이 적용된 모든 막대에 스킨이 값을 지정합니다. 끔: 각 막대가 자기 값을 유지합니다."
L["On: the spell's own requirement decides (a proc, enough mana), even on cooldown. Off: only when it can be cast now."] = "켬: 주문 자체의 조건(발동, 충분한 마나)으로 판단하며, 재사용 대기 중이어도 적용됩니다. 끔: 지금 시전할 수 있을 때만 적용됩니다."
L["On: the trigger fires for your pet's casts of the spell as well as yours."] = "켬: 내 시전뿐 아니라 내 소환수가 이 주문을 시전할 때도 트리거가 실행됩니다."
L["On: this opacity while none is left. Off: it keeps its opacity."] = "켜면 남은 것이 없을 때 이 투명도를 씁니다. 끄면 기존 투명도를 유지합니다."
L["On: this opacity while toggled on. Off: it keeps its opacity."] = "켬: 토글이 켜진 동안 이 투명도를 적용합니다. 끔: 자체 투명도를 유지합니다."
L["On: this trigger has its own pulse duration and animation tuning. Off drops them, and the reminder's apply."] = "켜면 이 트리거가 자체 펄스 지속시간과 애니메이션 조정을 가집니다. 끄면 이를 버리고 알림의 설정을 적용합니다."
L["Once an ability is off cooldown."] = "능력의 재사용 대기시간이 끝나면."
L["Once the proc glow goes, the pulse this trigger started leaves the screen, the queue and the hold."] = "발동 반짝임이 사라지면 이 트리거가 시작한 펄스는 화면, 대기열, 유지 상태에서 제거됩니다."
L["Once the spell stops being usable, the pulse this trigger started leaves the screen, the queue and the hold."] = "주문을 더 이상 사용할 수 없게 되면 이 트리거가 시작한 펄스는 화면, 대기열, 유지 상태에서 제거됩니다."
L["One card per element with its preview, kind, load conditions, Edit and Delete."] = "요소마다 카드 하나에 미리 보기, 종류, 불러오기 조건, 편집, 삭제가 있습니다."
L["One color"] = "단일 색상"
L["One editor for every selected icon (or bar): the rows they all share, read from the first one; a change lands on all of them."] = "선택한 모든 아이콘(또는 막대)을 한 번에 편집합니다. 모두가 공유하는 행을 첫 번째 항목에서 읽어 오며, 변경하면 모두에 적용됩니다."
L["One layer for every element of this layout, or each element's own layer moved up or down."] = "이 구성의 모든 요소에 계층 하나를 적용하거나, 각 요소의 자체 계층을 위나 아래로 옮깁니다."
L["One look"] = "모양 하나"
L["One motion (seconds)"] = "한 번 움직임 (초)"
L["One option of a choice talent"] = "선택 특성의 선택지 하나"
L["One per tick"] = "틱마다 하나"
L["One pulse (seconds)"] = "한 번 펄스 (초)"
L["One run (seconds)"] = "한 번 실행 (초)"
L["One setup for all your characters, and your kick macros become account macros. Your kick spell stays per character."] = "모든 캐릭터에 같은 설정을 쓰며, 차단 매크로가 계정 공용 매크로가 됩니다. 차단 주문은 캐릭터별로 유지됩니다."
L["One stance"] = "태세 하나"
L["One totem, by its spell ID"] = "토템 하나 (주문 ID로)"
L["One totem: any rank, any slot. A totem slot: whatever is in it. My totem bar's pick: its totem, shown with none down; click drops it."] = "토템 하나: 등급과 슬롯 무관. 토템 슬롯: 슬롯에 무엇이 있든 따라갑니다. 내 토템바의 선택: 토템바의 토템을 설치된 토템이 없을 때도 표시하며, 클릭하면 설치합니다."
L["One you have not learned yet stays grey until you do."] = "아직 배우지 않은 것은 배울 때까지 회색으로 남습니다."
L["One-time catch-up: moves EVERY action bar spell to the top rank you know, including lower ranks you placed on purpose."] = "일회성 정리: 의도적으로 배치한 낮은 등급을 포함해 모든 행동 단축바 주문을 알고 있는 가장 높은 등급으로 바꿉니다."
L["Only a spell row has a cost to mark."] = "비용을 표시할 수 있는 것은 주문 행뿐입니다."
