L["Opens Import / Export with exactly this selection ticked and its share string ready to copy."] = "이 선택 항목만 체크된 상태로 가져오기 / 내보내기를 열고 공유 문자열을 바로 복사할 수 있게 합니다."
L["Opens Import / Export with just this reminder ticked and its share string ready to copy."] = "가져오기 / 내보내기를 열고 이 알림만 선택해, 공유 문자열을 복사할 수 있게 준비합니다."
L["Opens Import / Export with just this ticked and its share string ready to copy."] = "가져오기 / 내보내기를 열고 이것만 선택해 공유 문자열을 복사할 수 있게 준비합니다."
L["Opens a picker for this group's spells and items right after Create. Out of combat only."] = "만들기 직후 이 그룹의 주문과 아이템을 고르는 선택창을 엽니다. 비전투 중에만 가능합니다."
L["Opens every More options fold in the editors, so the fine-tuning rows show without a click. Off: they wait behind their fold."] = "편집기의 모든 '설정 더 보기' 접기를 열어, 클릭 없이 세부 조정 행을 표시합니다. 끄면 접힌 채로 둡니다."
L["Opens it. The Anchor panel on its Position tab holds the link back to this one."] = "엽니다. 그 위치 탭의 기준점 패널에 이 항목으로 되돌아오는 링크가 있습니다."
L["Opens its editor."] = "편집기를 엽니다."
L["Opens the Add window aimed at this element."] = "이 요소를 대상으로 추가 창을 엽니다."
L["Opens the Add window for a spell, an item, a weapon enchant or a missing aura to be reminded of."] = "주문, 아이템, 무기 마법부여 또는 없을 때 알릴 오라를 추가하는 창을 엽니다."
L["Opens the talent tree: click a talent for this rule, again for Not taken."] = "특성 트리를 엽니다. 특성을 클릭하면 이 규칙에 적용되고, 다시 클릭하면 '선택 안 함'입니다."
L["Opens the talent tree: the bar keeps one look while you have the talent you pick, one while you don't."] = "특성 트리를 엽니다. 고른 특성이 있을 때와 없을 때 막대가 각각 하나의 모양을 유지합니다."
