L["Other heals color"] = "다른 치유 색상"
L["Other spells this icon can show, separated by commas. It turns to the last of them you cast, else shows the first one you know."] = "이 아이콘이 표시할 수 있는 다른 주문으로, 쉼표로 구분합니다. 마지막으로 시전한 주문으로 바뀌며, 없으면 알고 있는 첫 번째 주문을 표시합니다."
L["Out of Shadowform"] = "어둠의 형상 아님"
