L["Put it back"] = "되돌려 놓기"
L["Puts a ready-made macro in the box below. Save to use it."] = "만들어 둔 매크로를 아래 입력란에 넣습니다. 사용하려면 저장하십시오."
L["Puts back what the update changed, added or removed. The layout's page offers it too, until its next update."] = "업데이트가 바꾸거나 추가하거나 제거한 것을 되돌립니다. 다음 업데이트 전까지는 구성 페이지에서도 할 수 있습니다."
L["Puts back what the update changed, added or removed. Your changes since to the items it changed go too."] = "업데이트가 바꾸거나 추가하거나 제거한 것을 되돌립니다. 이후 변경된 아이템에 가한 내 변경도 함께 되돌려집니다."
L["Puts each layout's bars and free icons in the sidebar under BARS and FREE ICONS folds. Off: they list in place among its groups."] = "각 구성의 막대와 자유 아이콘을 사이드바의 막대 및 자유 아이콘 접기 아래에 둡니다. 끄면: 그룹 사이 제자리에 표시됩니다."
L["Puts it back at once when the game or another addon moves it. Off: it goes back the next time the group moves."] = "게임이나 다른 애드온이 옮기면 즉시 되돌려 놓습니다. 끔: 다음에 그룹이 움직일 때 되돌아갑니다."
L["Puts the layout's center point in the middle of your screen."] = "구성의 중심점을 화면 중앙에 놓습니다."
L["Puts the middle of what's shown in the middle of your screen. Scale grows from there."] = "표시된 항목의 가운데를 화면 가운데에 놓습니다. 크기 조절은 그곳을 기준으로 커집니다."
L["Puts the picked template's spells on the wheel, in place of what is on it now."] = "고른 템플릿의 주문을 지금 휠에 있는 것 대신 휠에 올립니다."
L["Puts the piece above back where it ships, with its color and size."] = "위의 요소를 색상과 크기를 포함해 기본 상태로 되돌립니다."
