L["Text color outside the thresholds"] = "기준값 밖 텍스트 색상"
L["Text element"] = "텍스트 요소"
L["Text font"] = "텍스트 글꼴"
L["Text in the band's color"] = "구간 색상으로 텍스트"
L["Text outline"] = "텍스트 외곽선"
L["Text shadow"] = "텍스트 그림자"
L["Text size"] = "텍스트 크기"
L["Text threshold %d color"] = "텍스트 기준값 %d 색상"
L["Text threshold %d value"] = "텍스트 기준값 %d 값"
L["Text threshold colors"] = "텍스트 기준값 색상"
L["Text thresholds in power units"] = "자원 단위 텍스트 기준값"
L["Text to Speech"] = "텍스트 음성 변환"
L["Text to speech: when set, it is spoken instead of the sound."] = "텍스트 음성 변환: 설정하면 소리 대신 음성으로 읽습니다."
L["Text type"] = "텍스트 유형"
L["Texts"] = "텍스트"
L["Texts take the bar's color"] = "텍스트에 막대 색상 적용"
L["Texture"] = "텍스처"
L["Texture  -  %s"] = "텍스처  -  %s"
L["Texture name"] = "텍스처 이름"
L["Textures"] = "텍스처"
L["Textures you use show here."] = "사용한 텍스처가 여기에 표시됩니다."
L["That anchor target no longer exists, so it stays free."] = "그 기준 대상이 더 이상 없어 자유 위치에 있습니다."
L["That frame can't move this way: an Arc Auras frame, the whole screen, or what this group is anchored to."] = "이 방식으로는 그 프레임을 움직일 수 없습니다: Arc Auras 프레임, 화면 전체, 또는 이 그룹이 기준점으로 삼은 대상."
L["That is not a spell ID."] = "주문 ID가 아닙니다."
L["That paste came in cut short. Paste it once more."] = "붙여넣기가 중간에 잘렸습니다. 한 번 더 붙여넣으세요."
L["The "] = "해당 "
L["The Active look, its timer running with its swipe and duration text. Drag any text on the icon to place it."] = "활성 모양입니다. 타이머가 스와이프 및 지속시간 텍스트와 함께 진행됩니다. 아이콘의 텍스트를 끌어 위치를 정하십시오."
L["The Algeth'ar Puzzle Box's haste: 20 seconds from its use; dying clears it."] = "알게타르 수수께끼 상자의 가속: 사용 후 20초이며, 죽으면 사라집니다."
L["The Arc Proc's own"] = "Arc 발동 자체 값"
L["The Cooldown Manager look draws the border and the shadow."] = "재사용 대기시간 관리자 모양이 테두리와 그림자를 그립니다."
L["The Cooldown Manager look sets the picture's size, crop and shape."] = "재사용 대기시간 관리자 모양이 그림의 크기, 자르기, 형태를 정합니다."
L["The Cooldown Manager's cooldown IDs for spells, auras and trinkets, one line per category. Runs of IDs show as ranges."] = "주문, 오라, 장신구의 재사용 대기시간 관리자 ID입니다. 분류마다 한 줄이며 연속된 ID는 범위로 줄입니다."
L["The Cooldown Manager's soft shadow frame around the icon art."] = "아이콘 아트 주위에 재사용 대기시간 관리자의 부드러운 그림자 프레임을 그립니다."
L["The ID block shows only when Shift is held as the tooltip opens."] = "툴팁이 열릴 때 Shift를 누르고 있어야 ID 블록이 표시됩니다."
L["The ID of what the tooltip shows: a spell, aura, item, toy, mount, currency, achievement or quest."] = "툴팁이 보여 주는 대상의 ID입니다: 주문, 오라, 아이템, 장난감, 탈것, 화폐, 업적, 퀘스트."
L["The Light's Potential potion: 30 seconds from the drink, each drink restarts it; dying clears it."] = "빛의 잠재력 물약: 마신 뒤 30초이며, 마실 때마다 다시 시작하고, 죽으면 사라집니다."
L["The Not active look, with no timer running."] = "비활성 모양입니다. 타이머는 진행되지 않습니다."
L["The On cooldown look: the timer idle and its cooldown spell cooling down."] = "'대기 중' 모양: 타이머는 쉬고 있고 그 주문은 재사용 대기 중입니다."
L["The Ready look: the timer idle and its cooldown spell ready."] = "'준비' 모양: 타이머는 쉬고 있고 그 주문은 준비된 상태입니다."
L["The Timer running look, its timer frozen with its swipe and duration text. Drag any text on the icon to place it."] = "'타이머 실행 중' 모양입니다. 타이머가 스와이프 및 지속시간 텍스트와 함께 멈춰 있습니다. 아이콘의 텍스트를 끌어 위치를 정하십시오."
L["The Tracked Bars entry this bar copies. Keep the Cooldown Manager's own bar on, and hide it with opacity 0 in Edit Mode."] = "이 막대가 복사하는 추적 중인 막대 항목입니다. 재사용 대기시간 관리자 자체의 막대는 켜 두고, 숨기려면 편집 모드에서 투명도를 0으로 설정하세요."
L["The action bar's yellow check on the icon while it waits for your next swing."] = "다음 스윙을 기다리는 동안 아이콘에 표시되는 행동 단축바의 노란 체크입니다."
L["The art's spell"] = "아트의 주문"
L["The aura at 3 stacks."] = "중첩 3개인 오라입니다."
L["The aura comes up with a fake duration (swipe and duration text), drops to its missing look, and comes back."] = "오라가 가짜 지속시간(스와이프와 지속시간 텍스트)과 함께 나타났다가, 없음 모양으로 바뀐 뒤 다시 돌아옵니다."
L["The aura counts down, drops off, and comes back: threshold colours and the duration text."] = "오라가 줄어들다가 사라지고 다시 돌아옵니다: 기준값 색상과 지속시간 텍스트."
L["The aura icons in this group are kept for when you switch back."] = "이 그룹의 오라 아이콘은 다시 전환할 때를 위해 보관됩니다."
L["The aura lasts"] = "오라 지속"
L["The aura lasts (seconds)"] = "오라 지속 (초)"
L["The aura with 60% of its duration left."] = "지속시간이 60% 남은 오라입니다."
L["The aura's full length, which the game keeps from addons: seconds need it, percent does not. 0 = not set: always shown."] = "오라의 전체 길이로, 게임이 애드온에게 숨기는 값입니다. 초 단위에는 필요하고 퍼센트에는 필요 없습니다. 0 = 미설정: 항상 표시."
L["The aura's full length. The game hides it from addons, so seconds thresholds need it. 0 = not set: the glow shows the whole time."] = "오라의 전체 길이입니다. 게임이 애드온에게 숨기므로 초 단위 기준값에 필요합니다. 0 = 미설정: 반짝임이 내내 표시됩니다."
L["The aura's icon"] = "오라의 아이콘"
L["The aura's spell ID, or the spell whose cooldown it follows: an ID, a link or the name of a spell you know. Enter applies it."] = "오라의 주문 ID 또는 그 재사용 대기시간을 따를 주문입니다: ID, 링크 또는 알고 있는 주문의 이름. Enter를 누르면 적용됩니다."
L["The aura's spell IDs, comma separated."] = "오라의 주문 ID를 쉼표로 구분해 입력합니다."
L["The aura's spell IDs, comma separated. Any caster's copy counts."] = "오라의 주문 ID를 쉼표로 구분해 입력합니다. 누가 건 오라든 해당됩니다."
L["The aura's spell IDs, separated by commas or spaces. Add every rank's ID if they differ. The game shows whichever is up."] = "오라의 주문 ID를 쉼표나 공백으로 구분해 입력합니다. 등급마다 다르면 모든 등급의 ID를 추가하십시오. 게임은 활성화된 것을 표시합니다."
L["The aura's spell IDs, separated by commas or spaces. Tracking sets its unit."] = "오라의 주문 ID를 쉼표나 공백으로 구분해 입력합니다. '추적'이 유닛을 정합니다."
L["The aura's spell IDs, separated by commas or spaces; any of them counts."] = "오라의 주문 ID를 쉼표나 공백으로 구분해 입력하며, 그중 하나라도 해당됩니다."
L["The aura's spell IDs, separated by commas or spaces; any of them shows the picture."] = "오라의 주문 ID를 쉼표나 공백으로 구분해 입력하며, 그중 하나라도 있으면 그림이 표시됩니다."
L["The aura's spell IDs, separated by commas. A debuff usually has the ID of the spell that puts it up."] = "오라의 주문 ID를 쉼표로 구분해 입력합니다. 약화 효과는 보통 이를 거는 주문의 ID를 가집니다."
L["The band your target is in; blank with no target or a friendly one."] = "대상이 속한 구간입니다. 대상이 없거나 아군이면 비어 있습니다."
L["The bar"] = "해당 막대"
L["The bar at 3 stacks, or at its Max stacks when that is lower."] = "중첩 3개인 막대입니다. 최대 중첩이 그보다 낮으면 최대 중첩 기준입니다."
L["The bar at 60%, standing still."] = "60%에서 멈춘 막대입니다."
L["The bar between swings."] = "스윙 사이의 막대입니다."
L["The bar in the middle of a cast, standing still."] = "시전 중간에서 멈춘 막대입니다."
L["The bar is full at this many stacks. Empty: the maximum the game reports, shown in the field. Type a number only if it is wrong."] = "이 중첩 수에서 막대가 가득 찹니다. 비우면 게임이 알려 주는 최댓값(입력란에 표시)을 씁니다. 그 값이 틀릴 때만 숫자를 입력하십시오."
L["The bar part way through its timer."] = "타이머 중간쯤 진행된 막대입니다."
L["The bar shows half the power; past the middle it fills again in the second half color."] = "막대는 자원의 절반을 표시합니다. 가운데를 넘으면 후반부 색상으로 다시 채워집니다."
L["The bar when the reload is done but you are moving: the shot waits for you to stop."] = "재장전은 끝났지만 이동 중일 때의 막대입니다. 멈출 때까지 사격이 기다립니다."
L["The bar with no timer running."] = "타이머가 진행되지 않는 막대입니다."
L["The bar's look."] = "막대의 모양입니다."
L["The bar's own look"] = "막대 자체의 모양"
L["The bars that wear it keep its look as their own."] = "이 스킨을 쓰는 막대는 그 모양을 자기 것으로 유지합니다."
L["The border always shows while the window is unlocked."] = "창이 잠금 해제된 동안에는 테두리가 항상 표시됩니다."
L["The brief lock some charge spells have after each cast never greys the icon. Longer locks still show."] = "일부 충전 주문이 시전 후 잠시 잠기는 동안 아이콘을 흑백으로 바꾸지 않습니다. 더 긴 잠김은 그대로 표시됩니다."
L["The buff this totem gives you, as its tooltip names it. The Out of range look shows while the totem is out and you lack it."] = "이 토템이 내게 거는 강화 효과이며, 툴팁에 적힌 이름입니다. 토템이 놓여 있는데 내게 없는 동안 '사정거리 밖' 모양이 표시됩니다."
L["The chance climbs 1% per Riptide since the last proc."] = "마지막 발동 이후 성난 해일마다 확률이 1%씩 올라갑니다."
L["The chance climbs per qualifying harvest; needs the 2-piece set."] = "조건에 맞는 수확마다 확률이 올라갑니다. 2세트 효과가 필요합니다."
L["The chance of a proc"] = "발동 확률"
L["The class this skin switches on for."] = "이 스킨이 켜지는 직업입니다."
L["The color %s."] = "%s의 색상입니다."
L["The cooldown lasts (seconds)"] = "재사용 대기시간 (초)"
L["The cooldown swipe keeps its own opacity while the icon dims, so only the art fades."] = "아이콘이 흐려져도 재사용 대기시간 스와이프는 자체 투명도를 유지하므로 아트만 흐려집니다."
L["The count"] = "개수"
L["The count of your equipped ammo; blank with the slot empty."] = "장착한 탄약의 개수입니다. 칸이 비어 있으면 비어 있습니다."
L["The count the \"Ammo is low\" load and visibility condition uses. An icon's warning glow and ammo count colors have their own thresholds."] = "\"탄약 부족\" 불러오기 및 표시 조건이 사용하는 개수입니다. 아이콘의 경고 반짝임과 탄약 개수 색상에는 각자의 기준값이 있습니다."
L["The countdown stays hidden until this many seconds are left."] = "남은 시간이 이 초 이하가 될 때까지 초읽기를 숨깁니다."
L["The deck half drawn, with a mark where each proc landed."] = "절반쯤 뽑은 덱이며, 발동이 일어난 위치마다 표시가 있습니다."
L["The dim copy stays when the picture hides: no aura, no timer, a cooldown not ready."] = "그림이 숨겨져도 흐린 사본은 남습니다: 오라 없음, 타이머 없음, 재사용 대기시간 미준비."
L["The end of your cast that your connection's delay covers: start the next cast once the fill reaches it."] = "연결 지연이 차지하는 시전의 끝부분입니다. 채우기가 여기에 닿으면 다음 시전을 시작하십시오."
L["The fill behind this group while the options window is open; opacity 0 means none."] = "설정 창이 열려 있는 동안 이 그룹 뒤에 깔리는 채우기입니다. 투명도 0이면 없음."
L["The fill shows how many of this deck's procs are used: none, some or all. Off: the Fill color."] = "채우기가 이 덱의 발동 사용 정도(없음, 일부, 모두)를 표시합니다. 끄면 채우기 색상을 씁니다."
L["The first time you log in after Arc Auras updates, a window opens once with what changed in the new version."] = "Arc Auras가 업데이트된 뒤 처음 접속하면, 새 버전의 변경 사항을 담은 창이 한 번 열립니다."
L["The full look starts out of combat, or after a /reload."] = "전체 모양은 비전투 상태이거나 /reload 후에 시작됩니다."
L["The game does not let addons match this aura type on that unit by spell ID."] = "게임은 애드온이 그 유닛의 이 오라 유형을 주문 ID로 대조하는 것을 허용하지 않습니다."
L["The game draws it with the aura, in combat too. Buffs work on you, your pet and friendly units; debuffs on a hostile target or focus."] = "게임이 오라와 함께 그리며, 전투 중에도 마찬가지입니다. 강화 효과는 자신, 소환수, 아군 유닛에게 적용되고, 약화 효과는 적대적인 대상이나 주시 대상에게 적용됩니다."
L["The game frame's name, as Pick Frame shows it. Enter applies it."] = "'프레임 선택'에 표시되는 게임 프레임의 이름입니다. Enter를 누르면 적용됩니다."
L["The game holds this frame still in combat. It moves when combat ends."] = "게임이 전투 중에는 이 프레임을 고정해 둡니다. 전투가 끝나면 움직입니다."
L["The game keeps an aura's length from addons, so seconds need it. A share needs none."] = "게임은 오라의 지속시간을 애드온에 알려 주지 않으므로 초 단위에는 그 값이 필요합니다. 비율은 필요 없습니다."
L["The game keeps the aura's length from addons: 0 shows the words the whole time it is up."] = "게임은 오라의 지속시간을 애드온에 알려 주지 않습니다: 0이면 오라가 있는 내내 문구를 표시합니다."
L["The game plays aura sounds itself, so they work in combat, for anyone's copy of the aura."] = "게임이 오라 소리를 직접 재생하므로 전투 중에도 작동하며, 누가 건 오라든 마찬가지입니다."
L["The game plays it, in combat too; Load When and the gap between cues don't apply."] = "게임이 직접 재생하며 전투 중에도 작동합니다. 불러올 조건과 신호 간격은 적용되지 않습니다."
L["The game protects %s, so it stays free."] = "%s: 게임이 보호하는 프레임이므로 자유 위치에 있습니다."
L["The game sent a spell update"] = "게임이 주문 갱신을 보냄"
L["The game's Enable Pings or Show Pings in Chat setting is off, so no pings reach the feed."] = "게임의 '핑 활성화' 또는 '대화창에 핑 표시' 설정이 꺼져 있어 핑이 목록에 전달되지 않습니다."
L["The game's clock, as the minimap shows it."] = "미니맵에 표시되는 게임 시계입니다."
L["The game's debuff border"] = "게임 약화 효과 테두리"
L["The game's own cooldown and buff icons and bars, as in its options. Items pinned to its icons stand free until it is back on."] = "게임 설정에 있는 게임 자체의 재사용 대기시간 및 강화 효과 아이콘과 막대입니다. 그 아이콘에 고정된 항목은 다시 켜질 때까지 자유 상태로 있습니다."
L["The game's own gold art, untinted, so the color steps aside. Intensity still applies."] = "색조 없는 게임 고유의 금색 아트라서 색상은 적용되지 않습니다. 강도는 계속 적용됩니다."
L["The global name of a frame, e.g. ElvUF_Player. A frame that does not exist counts as not there."] = "프레임의 전역 이름입니다 (예: ElvUF_Player). 존재하지 않는 프레임은 없는 것으로 취급합니다."
L["The global name of a game frame, e.g. PlayerFrame or ElvUF_Player."] = "게임 프레임의 전역 이름입니다 (예: PlayerFrame 또는 ElvUF_Player)."
L["The glow waits for combat; out of combat the bar shows without it."] = "반짝임은 전투를 기다립니다. 비전투 중에는 막대가 반짝임 없이 표시됩니다."
L["The glow waits for combat; out of combat the icon shows without it."] = "반짝임은 전투를 기다립니다. 비전투 중에는 아이콘이 반짝임 없이 표시됩니다."
L["The green outline and dark fill around each group while this window is open. Nothing shows groups as in play. Name tabs still work."] = "이 창이 열려 있는 동안 각 그룹 주위에 표시되는 초록 외곽선과 어두운 채우기입니다. '없음'이면 그룹을 플레이 때처럼 표시하며, 이름 탭은 계속 쓸 수 있습니다."
L["The group"] = "해당 그룹"
L["The group takes its %s with it."] = "그룹의 %s도 함께 삭제됩니다."
L["The group's box hugs the icons that are showing; anything anchored to it moves with it."] = "그룹 상자가 표시 중인 아이콘에 맞춰 줄어들고, 여기에 고정된 것도 함께 움직입니다."
L["The group's point"] = "그룹의 지점"
L["The group's spot can't be read right now. The frame moves once it can."] = "지금은 그룹의 위치를 읽을 수 없습니다. 읽을 수 있게 되면 프레임이 움직입니다."
L["The groups take their %s with them."] = "그룹들의 %s도 함께 삭제됩니다."
L["The health preview: 65% health with incoming heals and shields, in your colours and texts."] = "생명력 미리 보기: 생명력 65%에 들어오는 치유와 보호막을 더해, 내 색상과 텍스트로 표시합니다."
L["The icon"] = "아이콘"
L["The icon and bar previews sit on this color."] = "아이콘과 막대 미리 보기가 이 색상 위에 놓입니다."
L["The icon as the game's Cooldown Manager draws it: its rounded corners, its border and shadow, and its swipe."] = "게임의 재사용 대기시간 관리자처럼 둥근 모서리, 테두리와 그림자, 스와이프로 아이콘을 그립니다."
L["The icon's art and border at this opacity while the rule holds. 0% hides the whole icon, texts and glows too."] = "규칙이 유지되는 동안 아이콘의 그림과 테두리가 이 투명도로 표시됩니다. 0%이면 아이콘 전체와 텍스트, 반짝임도 숨겨집니다."
L["The icon's cooldown ID, its exact entry in the Cooldown Manager: Pick Frame on an icon fills it. Empty uses the spell above."] = "아이콘의 재사용 대기시간 ID, 재사용 대기시간 관리자에서의 정확한 항목입니다. 아이콘에서 프레임 선택을 하면 채워집니다. 비워 두면 위의 주문을 사용합니다."
L["The icon's exact entry in the Cooldown Manager; Pick Frame on an icon fills it. Empty uses the spell above."] = "재사용 대기시간 관리자에서의 아이콘 정확한 항목입니다. 아이콘에서 '프레임 선택'으로 채울 수 있습니다. 비우면 위의 주문을 사용합니다."
L["The icon's file ID, the base icon when an override swapped the art, and the icon the button shows when that differs."] = "아이콘의 파일 ID, 대체로 아트가 바뀐 경우의 기본 아이콘, 그리고 다를 경우 버튼에 보이는 아이콘입니다."
L["The import did not run."] = "가져오기가 실행되지 않았습니다."
L["The internal cooldown as a timer: 45 s, less with Natural Harmony."] = "내부 재사용 대기시간을 타이머로 표시합니다: 45초이며, 자연 친화가 있으면 더 짧아집니다."
L["The item"] = "해당 아이템"
L["The item's own stacks, before this rule acts. Empty = no such condition."] = "이 규칙이 작동하기 전 아이템 자체의 중첩입니다. 비우면 그런 조건이 없습니다."
L["The item, or several: the icon shows the first one you carry and can use."] = "아이템 하나 또는 여러 개: 아이콘은 지닌 것 중 사용할 수 있는 첫 번째 아이템을 표시합니다."
L["The items that used the old values take the new ones."] = "이전 값을 쓰던 아이템이 새 값을 적용받습니다."
L["The items you have keep their look; only new ones start with these. Leaving the page does the same."] = "이미 있는 아이템은 모양을 유지하고, 새 아이템만 이 값으로 시작합니다. 페이지를 나가도 같습니다."
L["The kinds that take this page's rows, each where it has the row. Nothing happens until you press Copy."] = "이 페이지의 행을 받을 종류이며, 각각 해당 행이 있는 곳에 적용됩니다. 복사를 누르기 전에는 아무 일도 일어나지 않습니다."
L["The label's own color"] = "문구 자체 색상"
L["The last 0.5 s of the bar is Auto Shot's windup: it fills only while you stand still. Colors on the Appearance tab."] = "막대의 마지막 0.5초는 자동 사격 준비 동작입니다. 가만히 서 있을 때만 채워집니다. 색상은 외형 탭에서 고르십시오."
L["The layout's center point"] = "구성의 중심점"
L["The layout's distance from the spot it's pinned to, in whole units."] = "구성이 고정된 지점에서 떨어진 거리이며, 정수 단위입니다."
L["The line to speak."] = "읽을 문장입니다."
L["The look the rows below change. The bar shows it while you edit; anything a look leaves alone follows the bar's own."] = "아래 행이 바꾸는 모양입니다. 편집하는 동안 막대에 표시되며, 모양이 건드리지 않는 것은 막대 자체 설정을 따릅니다."
L["The look the rows below edit. Bar's own applies when no skin does. A skin applies when its conditions hold, first from the top."] = "아래 행들이 편집하는 모양입니다. 막대 자체는 적용되는 스킨이 없을 때 적용됩니다. 스킨은 조건이 맞을 때 적용되며 위에서부터 첫 번째가 우선합니다."
L["The look while the aura is missing: the ghost with its Missing icon, alpha and desaturation."] = "오라가 없는 동안의 모양: 흐릿한 잔상에 '없음' 아이콘, 투명도, 흑백이 적용됩니다."
L["The look while the aura is up: Aura Active art, alpha, tint, border and glow. Drag any text to place it."] = "오라가 있는 동안의 모양: 오라 활성 아트, 투명도, 색조, 테두리, 반짝임. 텍스트를 끌어 위치를 정하십시오."
L["The look while the aura is up: its button over the cooldown, in the Aura Active look, with stacks. Drag texts to place them."] = "오라가 있는 동안의 모양: 재사용 대기시간 위에 오라 활성 모양의 오라 버튼이 중첩과 함께 표시됩니다. 텍스트를 끌어 위치를 정하십시오."
L["The look while you are in the stance (any stance, for your current one). Drag any text on the icon to place it."] = "태세에 있는 동안의 모양입니다 (현재 태세 항목은 아무 태세나 해당). 아이콘의 텍스트를 끌어 위치를 정하십시오."
L["The look while you are not in it (no stance, for your current one)."] = "태세에 있지 않은 동안의 모양입니다 (현재 태세 항목은 태세 없음)."
L["The macro this keeps updated. A new name takes over when you save."] = "이 항목이 계속 갱신하는 매크로입니다. 새 이름은 저장할 때 적용됩니다."
L["The mana the next tick adds glows past the fill, brightens as the tick nears, then lands. Empty while the five-second rule runs."] = "다음 틱에 들어올 마나가 채우기 너머에서 반짝이며, 틱이 가까워질수록 밝아지다가 들어옵니다. 5초 규칙 중에는 비어 있습니다."
L["The marker picker"] = "징표 선택창"
L["The marker your kick macros put on your focus and your group message names."] = "차단 매크로가 주시 대상에 붙이고 그룹 메시지에서 말하는 징표입니다."
L["The middle of your screen"] = "화면 중앙"
L["The mirror is not loaded."] = "미러가 불러와지지 않았습니다."
L["The move did not run."] = "이동이 실행되지 않았습니다."
L["The nearest band that shows, standing still."] = "표시되는 가장 가까운 구간에서 멈춘 모습입니다."
L["The new look shows after a reload"] = "UI를 다시 불러오면 새 모양이 표시됩니다"
L["The next tick"] = "다음 틱"
L["The number beside a marker that comes back in a later swing."] = "이후 스윙에서 돌아오는 표시 옆의 숫자입니다."
L["The numeric item ID."] = "숫자 아이템 ID입니다."
L["The opacity starts with this many seconds left."] = "남은 시간이 이 초에 이르면 이 투명도가 시작됩니다."
L["The original bright cyan."] = "원래의 밝은 청록색입니다."
L["The pack items you deleted come back with this update. Unticked, they stay deleted."] = "삭제한 팩 아이템이 이 업데이트와 함께 돌아옵니다. 체크하지 않으면 삭제된 상태로 유지됩니다."
L["The pack's name. Whoever imports the string sees it first."] = "팩의 이름입니다. 문자열을 가져오는 사람이 가장 먼저 보게 됩니다."
L["The part of a shield that doesn't fit past full health draws over the end of the health, so a shield on a full-health unit still shows."] = "최대 생명력을 넘는 보호막 부분은 생명력 끝 위에 그려지므로, 생명력이 가득한 유닛의 보호막도 보입니다."
L["The part of each entry the rows below place."] = "아래 행이 배치하는 각 항목의 부분입니다."
L["The picture again, dimmed, behind it: the empty part of a fill. It hides with the picture."] = "그림 뒤에 흐리게 다시 그린 그림으로, 채우기의 빈 부분입니다. 그림과 함께 숨겨집니다."
L["The picture as it looks while active; a fill or a ring stands at 60%."] = "활성 상태일 때의 그림 모습입니다. 채우기나 링은 60%에 멈춰 있습니다."
L["The picture grows and shrinks gently, in combat too."] = "그림이 부드럽게 커졌다 작아집니다. 전투 중에도 작동합니다."
L["The picture is a sheet of frames, played in order over and over."] = "그림은 프레임 시트이며, 순서대로 반복 재생됩니다."
L["The picture keeps its shape at any width and height: its edges are cropped, never stretched."] = "그림은 어떤 가로, 세로 길이에서도 비율을 유지합니다. 가장자리를 잘라 내며, 늘이지 않습니다."
L["The picture, border, swipe, shadow and glows follow the shape."] = "그림, 테두리, 스와이프, 그림자와 반짝임이 형태를 따릅니다."
L["The ping key works on every spell you have bound. Turn this on to keep it to the spells you pick on the Spells tab."] = "핑 단축키는 키가 지정된 모든 주문에 작동합니다. 켜면 주문 탭에서 고른 주문으로만 제한됩니다."
L["The point of the frame that goes on the group."] = "그룹에 붙는 프레임의 지점입니다."
L["The power this row holds on. All powers: whatever power the bar shows."] = "이 행이 적용되는 자원입니다. 모든 자원: 막대가 표시하는 자원이면 무엇이든."
L["The pulse stays at full, with no fade, until you cast the spell or use the item, or its trigger's Clear when ends it."] = "주문을 시전하거나 아이템을 사용하거나 트리거의 '지우기 조건'이 끝낼 때까지, 펄스가 페이드 없이 최대로 유지됩니다."
L["The ready look with no animation. Drag any text on the icon to place it."] = "애니메이션 없는 준비 모양입니다. 아이콘의 텍스트를 끌어 위치를 정하십시오."
L["The ready look, with the Ready text when it is on."] = "준비 모양이며, '준비' 텍스트를 켜 두었다면 함께 표시됩니다."
L["The reload is done but you are moving: the shot waits for you to stop."] = "재장전은 끝났지만 이동 중입니다. 멈출 때까지 사격이 기다립니다."
L["The resize lands when you let go of the slider."] = "슬라이더를 놓으면 크기가 바뀝니다."
L["The resource texts change color at their own power values, apart from the bar's colors."] = "자원 텍스트는 막대 색상과 별개로 자체 자원 값에서 색이 바뀝니다."
L["The resource texts wear the fill's color, the bar's own or a row's. A row's own text color wins."] = "자원 텍스트는 채우기 색상(막대 자체 색상 또는 행의 색상)을 씁니다. 행 자체의 텍스트 색상이 우선합니다."
L["The row holds for any spell left in it."] = "이 행은 남아 있는 주문이 하나라도 있으면 적용됩니다."
L["The rule fires only while this spell is off its cooldown (the GCD never counts). Empty = no such condition."] = "이 주문의 재사용 대기가 끝난 동안에만 규칙이 실행됩니다 (GCD는 계산하지 않음). 비우면 그런 조건이 없습니다."
L["The same enchant counting down, as it looks in play."] = "같은 마법부여가 줄어드는 모습이며, 실제 플레이 때의 모양입니다."
L["The same totem counting down, as it looks in play."] = "같은 토템이 줄어드는 모습이며, 실제 플레이 때의 모양입니다."
L["The set gate is the Set Pieces Rule on Load Conditions."] = "세트 조건은 불러오기 조건의 세트 부위 규칙입니다."
L["The sets on the gear you wear now are listed; with fewer pieces on, the item goes inert."] = "현재 착용한 장비의 세트가 나열됩니다. 착용 부위가 부족하면 아이템이 작동하지 않습니다."
L["The shield is in Appearance > Icon, the color in Appearance > Fill & Colors."] = "방패는 외형 > 아이콘에, 색상은 외형 > 채우기 및 색상에 있습니다."
L["The specs this skin switches on in. Pick several or Any spec."] = "이 스킨이 켜지는 전문화입니다. 여러 개를 고르거나 모든 전문화를 고르세요."
L["The spell that puts it down. The bar follows that totem or guardian, any rank, in any slot. Empty: whatever is in the slot."] = "이를 놓는 주문입니다. 막대가 어느 슬롯이든 그 토템이나 수호자를 따라가며 등급은 무관합니다. 비우면 슬롯에 있는 것이 무엇이든 따라갑니다."
L["The spell that puts it down. The icon follows that totem or guardian, any rank, in any slot. Empty: whatever is in the slot."] = "이를 놓는 주문입니다. 아이콘이 어느 슬롯이든 그 토템이나 수호자를 따라가며 등급은 무관합니다. 비우면 슬롯에 있는 것이 무엇이든 따라갑니다."
L["The spell that puts it down: the icon follows that totem or guardian, any rank, into whatever slot it lands."] = "이를 놓는 주문: 아이콘이 어느 슬롯에 놓이든 그 토템이나 수호자를 따라가며 등급은 무관합니다."
L["The spell that puts the totem down, any rank. Empty: this icon's spell."] = "토템을 놓는 주문이며 등급은 무관합니다. 비우면 이 아이콘의 주문입니다."
L["The spell whose button or icon it rides: a spell ID, a link or the name of a spell you know. Enter applies it."] = "버튼이나 아이콘을 따라갈 주문입니다: 주문 ID, 링크 또는 알고 있는 주문의 이름. Enter를 누르면 적용됩니다."
L["The spell whose button or icon it rides: an ID, a link or a known spell's name. Several ranks may be listed. Enter applies."] = "버튼이나 아이콘을 따라갈 주문입니다. ID, 링크, 알고 있는 주문의 이름을 쓸 수 있고 여러 등급을 나열할 수 있습니다. Enter를 누르면 적용됩니다."
L["The spell whose cooldown it shows. Empty: the art's spell."] = "재사용 대기시간을 표시할 주문입니다. 비우면 아트의 주문입니다."
L["The spell whose icon it wears. A spell ID, a link, or the name of a spell you know."] = "아이콘으로 쓸 주문입니다. 주문 ID, 링크 또는 알고 있는 주문의 이름."
L["The spell whose icon it wears; Appearance > Icon > Art > Custom icon wins over it. A spell ID, a link, or the name of a spell you know."] = "아이콘 모양으로 쓰는 주문입니다. 외형 > 아이콘 > 아트 > 사용자 설정 아이콘이 우선합니다. 주문 ID, 링크 또는 알고 있는 주문 이름입니다."
L["The spell whose range picks the band: a melee ability for Melee, a ranged spell for Caster. Empty: your class's usual one."] = "구간을 정할 사정거리 주문입니다. 근접에는 근접 능력, 시전자에는 원거리 주문을 씁니다. 비우면 직업의 기본 주문을 씁니다."
L["The spell whose range to your target decides the dim: an ID or a known spell's name. Empty: your class's usual one."] = "대상까지의 사정거리로 흐림을 정하는 주문입니다. 주문 ID 또는 알고 있는 주문 이름을 씁니다. 비우면 직업의 기본 주문을 씁니다."
L["The spell whose range to your target decides the rule: an ID or a known spell's name. Any rank works."] = "대상까지의 사정거리로 규칙을 정하는 주문입니다. 주문 ID 또는 알고 있는 주문 이름을 씁니다. 어느 등급이든 됩니다."
L["The spell's icon"] = "주문의 아이콘"
L["The spell's name or ID."] = "주문의 이름 또는 ID입니다."
L["The spells it watches (any spell but these: the ones it skips), comma separated: IDs, links or names. Any rank."] = "지켜볼 주문입니다 (이 주문들을 제외한 모든 주문: 건너뛰는 주문). 쉼표로 구분한 ID, 링크 또는 이름. 모든 등급이 해당됩니다."
L["The spells it watches, comma separated: IDs, links or names. Any rank."] = "감시할 주문을 쉼표로 구분해 입력합니다: ID, 링크 또는 이름. 모든 등급."
L["The spot on your screen the layout keeps its distance from when the resolution or UI scale changes."] = "해상도나 UI 크기가 바뀔 때 구성이 거리를 유지하는 화면상의 지점입니다."
L["The stack count"] = "중첩 수"
L["The stack count that fills it. 0 = the aura's most, or the custom item's Max stacks."] = "막대를 채우는 중첩 수입니다. 0 = 오라의 최댓값 또는 사용자 설정 항목의 최대 중첩."
L["The stacks"] = "중첩"
L["The stacks climb to Max stacks, then clear: the fill and the count."] = "중첩이 최대 중첩까지 올라간 뒤 초기화됩니다: 채우기와 개수."
L["The stacks climb to the maximum and drop: stack colours, the max colour and the count."] = "중첩이 최대까지 올라간 뒤 떨어집니다: 중첩 색상, 최대 색상, 개수."
L["The stacks, then the timer in brackets: 3 (7.2)."] = "중첩 수, 이어서 괄호 안에 타이머: 3 (7.2)."
L["The stance or form you are in, or one lit while you are in it."] = "현재 있는 태세나 변신, 또는 해당 상태인 동안 켜지는 항목입니다."
L["The stance's spell ID: one this character does not have, such as another class's."] = "태세의 주문 ID입니다: 다른 직업의 것처럼 이 캐릭터에 없는 것도 가능합니다."
L["The state that lights it: an aura up or missing, or a spell Ready, Recharging (a charge used) or On cooldown (none left)."] = "아이콘을 밝히는 상태입니다: 오라가 있거나 없음, 또는 주문의 준비, 충전 중(충전 사용), 대기 중(남은 충전 없음)."
L["The swipe keeps its own opacity while Active opacity dims the icon, so only the art fades."] = "'활성' 투명도가 아이콘을 흐리게 해도 스와이프는 자체 투명도를 유지하므로 아트만 흐려집니다."
L["The text"] = "해당 텍스트"
L["The text to speak is set on each trigger."] = "말할 텍스트는 각 트리거에서 정합니다."
L["The text with a sample value, in its font, colour and box."] = "견본 값이 들어간 텍스트이며, 자체 글꼴, 색상, 상자를 사용합니다."
L["The texture"] = "해당 텍스처"
L["The time left"] = "남은 시간"
L["The time left on a weapon's enchant, with its charges."] = "무기 마법부여의 남은 시간과 충전 횟수입니다."
L["The time left on one of your totems or guardians, by the spell that puts it down or by its slot."] = "토템이나 수호자의 남은 시간이며, 이를 놓는 주문이나 슬롯으로 지정합니다."
L["The timer"] = "타이머"
L["The timer is not running"] = "타이머가 실행 중이 아님"
L["The timer is running"] = "타이머가 실행 중"
L["The timer runs"] = "타이머 실행"
L["The timer runs or it has stacks"] = "타이머 실행 또는 중첩 있음"
L["The timer runs or stacks are above 0"] = "타이머 실행 중 또는 중첩 0 초과"
L["The timer runs out, rests, and starts again."] = "타이머가 끝나고, 쉬었다가, 다시 시작합니다."
L["The top look wins when several hold."] = "여러 개가 해당하면 맨 위의 모양이 적용됩니다."
L["The totem bar button this icon follows."] = "이 아이콘이 따라가는 토템바 버튼입니다."
L["The totem or guardian slot to watch. The icon lights while anything is in it."] = "지켜볼 토템 또는 수호자 슬롯입니다. 슬롯에 무언가 있는 동안 아이콘이 켜집니다."
L["The totem or guardian slot to watch. The icon lights while anything is in it. A shaman's slots hold: %s."] = "지켜볼 토템 또는 수호자 칸입니다. 칸에 무엇이든 있으면 아이콘이 밝아집니다. 주술사의 칸: %s."
L["The tracked cooldown spell."] = "추적 중인 재사용 대기시간 주문입니다."
L["The tracked item, or several: the icon shows the first one you carry and can use. Retargeting keeps every setting and position."] = "추적할 아이템(여러 개 가능)입니다. 아이콘은 가지고 있고 사용할 수 있는 첫 번째 아이템을 표시합니다. 대상을 바꿔도 모든 설정과 위치가 유지됩니다."
L["The tracked spell. Retargeting re-keys the driver and keeps every setting and position."] = "추적할 주문입니다. 대상을 바꾸면 동작 키를 다시 정하고 모든 설정과 위치를 유지합니다."
L["The tracker's readout when you point at the icon. On also turns the icon's click-through off."] = "아이콘을 가리키면 추적기의 수치를 보여줍니다. 켜면 아이콘의 클릭 통과도 꺼집니다."
L["The unit's name"] = "유닛 이름"
L["The value counts power (45 energy, 2000 mana) instead of a percent of the bar."] = "막대의 퍼센트 대신 자원 값(기력 45, 마나 2000)을 셉니다."
L["The value runs from empty to full and back: threshold colours, pips and every text follow it."] = "값이 빈 상태에서 가득 찬 상태까지 오르내립니다: 기준값 색상, 점, 모든 텍스트가 이를 따릅니다."
L["The wheel"] = "해당 휠"
L["The wheel is full: empty a spot first."] = "휠이 가득 찼습니다. 먼저 칸을 하나 비우십시오."
L["The whole cooldown"] = "전체 재사용 대기시간"
L["The whole picture"] = "그림 전체"
L["The window a ready check opens: your marker, a group message and macros to drag onto your bars."] = "전투 준비 시 열리는 창입니다. 내 징표, 그룹 메시지, 행동 단축바로 끌어다 놓을 매크로가 있습니다."
L["The window keeps the size for Max entries shown and stays on screen when empty, instead of growing with each ping."] = "창이 '표시할 최대 항목 수' 크기를 유지하고 비어 있어도 화면에 남으며, 핑마다 커지지 않습니다."
L["The windup as it fills, and a faint outline of its spot while you reload."] = "채워지는 준비 동작, 그리고 재장전 중 그 자리를 보여 주는 흐린 윤곽선입니다."
L["Their own class and spec checks"] = "각자의 직업 및 전문화 확인"
L["Their own class checks"] = "각자의 직업 확인"
L["Then"] = "그다음"
L["Thick"] = "두껍게"
L["Thick line"] = "굵은 선"
L["Thick outline"] = "두꺼운 외곽선"
L["Thickness"] = "두께"
L["Thin"] = "얇게"
L["Thin line"] = "가는 선"
L["Third"] = "셋째"
L["Third ammo threshold (at or below)"] = "세 번째 탄약 기준값 (이하)"
L["Third ammo threshold color"] = "세 번째 탄약 기준값 색상"
L["Third threshold (%)"] = "세 번째 기준값 (%)"
L["Third threshold color"] = "세 번째 기준값 색상"
L["This %s fails its load conditions on this character (%s). You can still edit it. Click its eye to show it on screen."] = "이 %s|1은;는; 이 캐릭터에서 불러오기 조건을 만족하지 않습니다 (%s). 편집은 계속할 수 있습니다. 눈 아이콘을 클릭하면 화면에 표시합니다."
L["This bar doesn't load on this character (%s). Click its eye to show it while you edit."] = "이 막대는 이 캐릭터에서 불러오지 않습니다 (%s). 편집하는 동안 보이려면 눈 아이콘을 클릭하십시오."
L["This bar wears as many skins as it can."] = "이 막대는 가능한 한 많은 스킨을 적용받습니다."
L["This bar's aura"] = "이 막대의 오라"
L["This bar's name"] = "이 막대 이름"
L["This bar's spell"] = "이 막대의 주문"
L["This character"] = "이 캐릭터"
L["This frame stops moving with the group and goes back to where it was."] = "이 프레임은 그룹과 함께 움직이지 않고 원래 위치로 돌아갑니다."
L["This group doesn't load on this character (%s). Click its eye to show it while you edit."] = "이 그룹은 이 캐릭터에서 불러오지 않습니다 (%s). 편집하는 동안 보이려면 눈 아이콘을 클릭하십시오."
L["This group follows the cursor or a nameplate. A frame can't keep up with it."] = "이 그룹은 커서나 이름표를 따라갑니다. 프레임은 따라가지 못합니다."
L["This group holds %d icons, and they would not fit. Move one out first."] = "이 그룹에는 아이콘 %d개가 있어 들어가지 않습니다. 먼저 하나를 옮기십시오."
L["This group is not on screen, so the frame stays where it was."] = "이 그룹은 화면에 없으므로 프레임이 원래 위치에 남습니다."
L["This group reminds you of it already."] = "이 그룹이 이미 알려 주고 있습니다."
L["This group shows up to %d auras already."] = "이 그룹은 이미 최대 %d개의 오라를 표시하고 있습니다."
L["This hero tree is not the one chosen."] = "선택한 영웅 특성 트리가 아닙니다."
L["This icon doesn't load on this character (%s). Click its eye to show it while you edit."] = "이 아이콘은 이 캐릭터에서 불러오지 않습니다 (%s). 편집하는 동안 보이려면 눈 아이콘을 클릭하십시오."
L["This icon's own rules wait until Close gaps is off: set these on the Aura Group."] = "이 아이콘의 자체 규칙은 '빈틈 메우기'가 꺼질 때까지 대기합니다. 오라 그룹에서 설정하십시오."
L["This is how Arc Auras speaks."] = "Arc Auras는 이렇게 말합니다."
L["This item itself: not offered"] = "이 항목 자체: 제공되지 않음"
L["This key pings the spell and casts nothing. Right-click clears it."] = "이 키는 주문의 핑만 보내고 시전하지 않습니다. 오른쪽 클릭으로 지웁니다."
L["This layout doesn't load on this character (%s). Click its eye to show it while you edit."] = "이 구성은 이 캐릭터에서 불러오지 않습니다 (%s). 편집하는 동안 보이려면 눈 아이콘을 클릭하십시오."
L["This layout stops setting these. Everything that followed it goes back to its own defaults."] = "이 구성이 이 값들을 더 이상 지정하지 않습니다. 구성을 따르던 모든 것이 자체 기본값으로 돌아갑니다."
L["This option is active"] = "이 선택지가 활성 상태입니다"
L["This option is not active"] = "이 선택지가 비활성 상태입니다"
L["This piece is hidden: show it above to place it."] = "이 요소는 숨겨져 있습니다. 배치하려면 위에서 표시하십시오."
L["This spell has no charges: Recharging never lights."] = "이 주문에는 충전이 없습니다. '충전 중'은 켜지지 않습니다."
L["This string"] = "이 문자열"
