L["This string is older than your copy of %s: updating would bring back its older settings."] = "이 문자열은 내 %s 사본보다 오래되었습니다. 업데이트하면 이전 설정이 돌아옵니다."
L["This string updates items you have"] = "이 문자열은 보유한 항목을 업데이트합니다"
