L["Type the aura's name and click one to add its ID, or type IDs separated by commas or spaces. Any of them counts."] = "오라의 이름을 입력하고 하나를 클릭해 ID를 추가하거나, ID를 쉼표나 공백으로 구분해 입력하십시오. 그중 하나라도 해당됩니다."
