L["Type the buff's NAME to see the spell IDs that carry it, then click one (every rank comes along). Add the group version's too."] = "강화 효과의 이름을 입력해 그 효과를 가진 주문 ID를 확인한 뒤 하나를 클릭하십시오 (모든 등급이 함께 들어갑니다). 그룹 버전의 ID도 추가하십시오."
