L["Where a group, icon or bar shared without its layout lands. It starts on a layout that loads on this character."] = "구성 없이 공유된 그룹, 아이콘 또는 막대가 들어갈 곳입니다. 이 캐릭터에서 불러오는 구성으로 시작합니다."
L["Where an ability comes off cooldown: this swing, or a later one marked +1, +2."] = "능력의 재사용 대기시간이 끝나는 지점입니다: 이번 스윙, 또는 +1, +2로 표시된 이후 스윙."
L["Where an icon goes when it shows again. Only for a single row or column."] = "아이콘이 다시 나타날 때 들어갈 자리입니다. 한 행이나 한 열일 때만 해당합니다."
L["Where each item sits (its group, or free and where), its anchor, sizes, strata and mouse. Off keeps your own placement."] = "각 항목의 위치(소속 그룹 또는 자유 상태와 위치), 기준점, 크기, 프레임 계층, 마우스 설정입니다. 끄면 내 배치를 유지합니다."
L["Where it sits: its edge against the group's."] = "놓이는 위치: 이 항목의 가장자리가 그룹의 가장자리에 맞닿습니다."
L["Where on the group that point goes."] = "그 지점이 그룹의 어디에 놓일지 정합니다."
L["Where the layout's center point (the cross on the map) sits from the spot it's pinned to, in whole pixels."] = "구성의 중심점(지도의 십자)이 고정된 지점에서 얼마나 떨어져 있는지이며, 정수 픽셀 단위입니다."
L["Where the selection goes: free in a layout, or into a group for icons. A selected group brings its icons. Press Move or Copy to apply."] = "선택 항목이 갈 곳: 구성 안의 자유 위치, 또는 아이콘이면 그룹. 선택한 그룹은 아이콘도 함께 갑니다. 이동 또는 복사를 눌러야 적용됩니다."
L["Where they load"] = "불러오는 곳"
L["Where this sub-panel's rows go: all of this type, one layout, one group, one item, or all icons of this kind. Press Copy to apply."] = "이 하위 패널의 행을 보낼 곳입니다: 이 유형의 전부, 구성 하나, 그룹 하나, 항목 하나, 또는 이 종류의 모든 아이콘. 복사를 눌러야 적용됩니다."
L["Where to find the pack or you, a page or a Discord. It shows as text to copy."] = "팩이나 제작자를 찾을 수 있는 곳(웹 페이지 또는 Discord)입니다. 복사할 수 있는 텍스트로 표시됩니다."
L["Which Casts"] = "대상 시전"
L["Which of the game's volume sliders the sounds follow. Spoken words use WoW's text to speech volume."] = "소리가 따르는 게임의 음량 슬라이더입니다. 읽는 말은 WoW의 텍스트 음성 변환 음량을 씁니다."
L["Which one"] = "어느 것"
L["Which other windows the feed sits above or below."] = "핑 목록이 어떤 다른 창의 위 또는 아래에 놓일지 정합니다."
L["Which part of each picture stays when its edges are cropped."] = "가장자리를 자를 때 각 그림에서 남길 부분입니다."
L["Which part of the picture stays when its edges are cropped."] = "가장자리를 자를 때 그림에서 남길 부분입니다."
