L["While %s"] = "%s 상태일 때"
L["While a charge comes back it keeps Recharging's look: can't use, not enough resource and out of range wait until it is ready."] = "충전이 돌아오는 동안에는 '충전 중' 모양을 유지합니다. 사용 불가, 자원 부족, 사정거리 밖은 준비될 때까지 대기합니다."
L["While a totem or guardian from the first spell is out, the icon shows its time instead of the aura."] = "첫 번째 주문의 토템이나 수호자가 있는 동안, 아이콘은 오라 대신 그 시간을 표시합니다."
L["While active"] = "활성 중"
L["While all procs are used"] = "모든 발동 사용 중"
L["While all procs used"] = "모든 발동 사용 중"
L["While an ability waits to go off with your next swing."] = "능력이 다음 스윙에 나가기를 기다리는 동안."
L["While casting"] = "시전 중"
L["While equipped"] = "착용 중"
L["While in stock"] = "보유 중"
L["While it has %s"] = "%s인 동안"
L["While it is active"] = "활성 상태인 동안"
L["While it is on cooldown"] = "재사용 대기 중"
L["While it is queued without the rage or mana to pay for it, the icon takes this color: that swing lands as a plain hit."] = "분노나 마나가 부족한 채로 예약된 동안 아이콘이 이 색상이 됩니다. 그 스윙은 일반 공격으로 들어갑니다."
L["While it is ready"] = "준비된 동안"
L["While its charges are at a count"] = "충전 횟수가 정해진 개수인 동안"
L["While its proc is up"] = "발동이 활성인 동안"
L["While its stacks are at a count"] = "중첩이 정해진 개수인 동안"
L["While its timer is idle it shows this spell's cooldown, then its Ready look."] = "타이머가 대기 중이면 이 주문의 재사용 대기시간을 표시하고, 그다음 '준비' 모양을 표시합니다."
L["While missing"] = "없을 때"
L["While not active"] = "비활성 중"
L["While on cooldown"] = "대기 중"
L["While out of range"] = "사정거리 밖인 동안"
L["While out of stock"] = "보유 없음"
L["While procs are left"] = "발동이 남아 있는 동안"
L["While procs left"] = "발동이 남아 있는 동안"
L["While queued"] = "예약된 동안"
L["While ready"] = "준비된 동안"
L["While recharging"] = "충전 중인 동안"
L["While suggested"] = "추천 중"
L["While the aura is missing"] = "오라가 없는 동안"
L["While the aura is up"] = "오라가 있는 동안"
L["While the aura is up the game shows it over the icon: its time, and gone the moment it drops. Works in combat."] = "오라가 있는 동안 게임이 아이콘 위에 시간을 표시하고, 오라가 사라지는 즉시 없어집니다. 전투 중에도 작동합니다."
L["While the aura is up, its border takes the game's color for its type: Magic, Curse, Disease or Poison. Others keep the border color."] = "오라가 있는 동안 테두리가 유형별 게임 색상(마법, 저주, 질병, 독)을 씁니다. 유형이 없는 오라는 테두리 색상을 유지합니다."
L["While the aura is up, only once little time is left, only while the aura is missing, or always. Works in combat."] = "오라가 있는 동안, 남은 시간이 적을 때만, 오라가 없을 때만, 또는 항상. 전투 중에도 작동합니다."
L["While the button is held"] = "버튼을 누르고 있는 동안"
L["While the timer is idle at 0 stacks, the count shows this many: a pool reads full before its first use. Empty = off."] = "타이머가 중첩 0으로 대기 중일 때 이 개수를 표시합니다. 첫 사용 전에는 가득 찬 것으로 보입니다. 비우면 꺼짐."
L["While the timer runs"] = "타이머가 진행되는 동안"
L["While this bar is not loaded, its count stops until the next reset."] = "이 막대를 불러오지 않은 동안에는 다음 초기화까지 개수가 멈춥니다."
L["While this icon is not loaded, its count stops until the next reset."] = "이 아이콘을 불러오지 않은 동안에는 다음 초기화까지 개수가 멈춥니다."
L["While this page is open the window can be dragged, locked or not."] = "이 페이지가 열려 있는 동안에는 잠금 여부와 상관없이 창을 끌 수 있습니다."
L["While this window is open a dim icon marks the spot; drag its name tab to move it."] = "이 창이 열려 있는 동안 흐린 아이콘이 자리를 표시합니다. 이름 탭을 끌어서 옮기십시오."
L["While this window is open the outline marks the spot; drag its name tab to move it."] = "이 창이 열려 있는 동안 외곽선이 자리를 표시합니다. 이름 탭을 끌어서 옮기십시오."
L["While this window is open, a dim copy of the first reminder's icon marks where pulses land. On shows only the outline and name tab."] = "이 창이 열려 있는 동안 첫 번째 알림 아이콘의 흐린 사본이 펄스 위치를 표시합니다. 켜면 외곽선과 이름 탭만 표시합니다."
L["While this window is open, drag this item's texts where they sit on screen. X and Y follow."] = "이 창이 열려 있는 동안 이 항목의 텍스트를 화면에서 끌어 옮길 수 있습니다. X와 Y가 따라갑니다."
L["While this window is open, each group shows its name on its top edge, which you drag it by. Off: a small green handle, name on hover."] = "이 창이 열려 있는 동안 각 그룹의 위쪽 가장자리에 이름을 표시하며, 이것을 잡고 그룹을 끕니다. 끄면 작은 초록 손잡이가 남고 마우스를 올리면 이름이 보입니다."
L["While this window is open, icons and bars carry a small Edit button that opens them here. Pick which kind shows it, or none."] = "이 창이 열려 있는 동안 아이콘과 막대에 작은 편집 버튼이 붙어 여기에서 열 수 있습니다. 버튼이 붙을 종류를 고르거나 없음을 고릅니다."
L["While this window is open, items that fail their load conditions are drawn anyway, so you can place and style them."] = "이 창이 열려 있는 동안 불러오기 조건을 만족하지 않는 항목도 그려져, 배치하고 꾸밀 수 있습니다."
L["While this window is open, the group you edit shows edge arrows: green adds a row or column on that side, red removes one."] = "이 창이 열려 있는 동안 편집 중인 그룹의 가장자리에 화살표가 표시됩니다. 초록은 그쪽에 행이나 열을 추가하고, 빨강은 하나를 제거합니다."
L["While toggled on"] = "토글이 켜진 동안"
L["Who carries the aura. Buffs match on friends and you, debuffs on enemies."] = "오라를 가진 대상입니다. 강화 효과는 아군과 자신에게, 약화 효과는 적에게 적용됩니다."
L["Who carries the aura: a buff on you, a debuff on your target, or another unit."] = "오라를 가진 대상: 내게 걸린 강화 효과, 대상에게 걸린 약화 효과, 또는 다른 유닛."
L["Who carries the aura: buffs on you, your pet, party and friends, debuffs on enemies. The game hides the opposite from addons."] = "오라를 지닌 대상입니다. 강화 효과는 나, 소환수, 파티원, 아군에게서, 약화 효과는 적에게서 찾습니다. 그 반대는 게임이 애드온에 숨깁니다."
L["Who carries the aura: you for a buff, your target for a debuff. You, then your target: you first. Other combinations stay dark."] = "오라를 가진 대상: 강화 효과는 자신, 약화 효과는 대상입니다. '나, 그다음 대상'은 나를 먼저 확인합니다. 그 외 조합은 표시되지 않습니다."
L["Whole shards only"] = "온전한 조각만"
L["Whose aura"] = "누구의 오라"
L["Whose casts"] = "누구의 시전"
L["Wide (3:2)"] = "가로형 (3:2)"
L["Width"] = "가로 길이"
L["Width (0 = auto)"] = "가로 길이 (0 = 자동)"
L["Windfury Totem"] = "질풍의 토템"
L["Windfury Weapon"] = "질풍의 무기"
L["Window layer"] = "창 계층"
L["Windup"] = "준비 동작"
L["Windup color"] = "준비 동작 색상"
L["Wing Clip for melee, then Auto Shot with the 10 and 20 yard checks."] = "근접은 날개 절단, 이후 자동 사격으로 10미터와 20미터 확인을 합니다."
L["Wing Clip for melee, then Auto Shot with the 20 yard check."] = "근접은 날개 절단, 이후 자동 사격으로 20미터 확인을 합니다."
L["Wins over the rows below it."] = "아래 행보다 우선합니다."
L["With"] = "조건:"
L["With "] = "보유: "
L["With %s"] = "%s 있음"
L["With %s left. Click to change it."] = "%s 남았을 때. 클릭하면 바꿉니다."
L["With Close gaps on, set these on the Aura Group."] = "'빈틈 메우기'가 켜져 있으면 오라 그룹에서 설정하십시오."
L["With Close gaps on, the game places the row: these apply only while this window is open."] = "'빈틈 메우기'가 켜져 있으면 게임이 행을 배치하므로, 이 설정은 이 창이 열려 있을 때만 적용됩니다."
L["With a two-hander, a shield or nothing in this hand, the icon doesn't load. It comes back when you equip a weapon there."] = "이 손에 양손 무기나 방패가 있거나 아무것도 없으면 아이콘을 불러오지 않습니다. 그 손에 무기를 장착하면 다시 나타납니다."
L["With both aura types, or on nameplates, it shows as Colors and badges."] = "두 오라 유형을 함께 쓰거나 이름표에서는 '색상과 배지'로 표시됩니다."
L["With both, the hide list applies to the buffs only."] = "둘 다 쓰면 숨김 목록은 강화 효과에만 적용됩니다."
L["With both, the hide list applies to the debuffs only."] = "둘 다 쓰면 숨김 목록은 약화 효과에만 적용됩니다."
L["With more than one row and column, a returning icon always takes its spot back."] = "행과 열이 둘 이상이면 다시 나타나는 아이콘은 항상 자기 자리를 되찾습니다."
L["With no charges"] = "충전이 없을 때"
L["With or without a talent"] = "특성 보유 여부별"
L["With several out at once: the First, the Second... Counted by picks how they are counted."] = "여러 개가 동시에 있을 때: 첫째, 둘째... '세는 방식'이 세는 법을 정합니다."
L["With the bar"] = "막대와 함께"
L["With the look set here"] = "여기서 정한 모양으로"
L["With this window open, every icon keeps its spot."] = "이 창이 열려 있으면 모든 아이콘이 자리를 유지합니다."
L["With your weapon (%.2f speed)"] = "내 무기 기준 (속도 %.2f)"
L["Within"] = "범위 안"
L["Within (s)"] = "이내 (초)"
L["Within seconds"] = "초 이내"
L["Within seconds after rule"] = "규칙 후 초 이내"
L["Without "] = "미보유: "
L["Without %s"] = "%s 없음"
L["WoW Forever"] = "WoW Forever"
L["WoW Forever: follows the rank you currently know, by name, so a new rank needs no new ID. Off: tracks the exact ID above."] = "WoW Forever: 이름으로 지금 알고 있는 등급을 따라가므로 새 등급에 새 ID가 필요 없습니다. 끄면 위의 정확한 ID를 추적합니다."
L["WoW's own option: a short tick when a spoken line ends."] = "WoW 자체 옵션: 음성 안내가 끝나면 짧은 틱 소리를 냅니다."
L["WoW's own text to speech volume, so it also sets chat narration."] = "WoW 자체 텍스트 음성 변환 음량이므로 채팅 낭독에도 영향을 줍니다."
L["WoW's voice"] = "WoW 음성"
L["WoW's voice is the one picked in WoW's own options. Male or female picks a matching voice from your system's list."] = "WoW 음성은 WoW 자체 설정에서 고른 음성입니다. 남성 또는 여성을 고르면 시스템 목록에서 맞는 음성을 선택합니다."
L["Wobble"] = "흔들림"
L["Wobble (degrees)"] = "흔들림 (도)"
L["Words after the value. Not on a countdown the game draws (a spell's time left, an aura's)."] = "값 뒤에 붙는 문구입니다. 게임이 그리는 초읽기(주문의 남은 시간, 오라의 남은 시간)에는 적용되지 않습니다."
L["Words before the value. Not on a countdown the game draws (a spell's time left, an aura's)."] = "값 앞에 붙는 문구입니다. 게임이 그리는 초읽기(주문의 남은 시간, 오라의 남은 시간)에는 적용되지 않습니다."
L["Words to speak"] = "읽을 문구"
L["Words you type"] = "직접 입력한 문구"
L["Writes each element's name over its box, here and while you move the layout on screen."] = "각 요소의 이름을 상자 위에 표시합니다. 여기와 화면에서 구성을 옮기는 동안 모두 적용됩니다."
L["X %d, Y %d. Drag to move; the Text tab holds the sliders."] = "X %d, Y %d. 끌어서 옮기십시오. 슬라이더는 텍스트 탭에 있습니다."
L["X offset"] = "X 오프셋"
