L["You, then your target"] = "나, 그다음 대상"
L["Your Arc UI setup"] = "내 Arc UI 설정"
L["Your Arcane Blast stacks: up to 4, each cast restarts their 8 seconds; any other spell or dying clears them."] = "비전 작렬 중첩: 최대 4개이며, 시전할 때마다 8초가 다시 시작합니다. 다른 주문을 시전하거나 죽으면 사라집니다."
L["Your Casts"] = "내 시전"
L["Your Cooldown"] = "내 재사용 대기시간"
L["Your Cooldown Manager could not be read just now. Try again in a moment."] = "지금은 재사용 대기시간 관리자를 읽을 수 없습니다. 잠시 후 다시 시도하십시오."
L["Your Cooldown Manager layout is ready. Turn off the game's own Cooldown Manager now?\n\nSettings > Cooldown Manager turns it back on."] = "재사용 대기시간 관리자 구성이 준비되었습니다. 지금 게임의 재사용 대기시간 관리자를 끄시겠습니까?\n\n설정 > 재사용 대기시간 관리자에서 다시 켤 수 있습니다."
L["Your Cooldown Manager lists no auras here."] = "재사용 대기시간 관리자에 여기 표시할 오라가 없습니다."
L["Your Cooldown Manager shows no spells yet."] = "재사용 대기시간 관리자에 아직 표시되는 주문이 없습니다."
L["Your Cooldown Manager's bars as groups: same spells, sizes and places. Then hide its bars in Edit Mode."] = "재사용 대기시간 관리자의 막대를 그룹으로 만듭니다: 같은 주문, 크기, 위치. 이후 편집 모드에서 해당 막대를 숨기십시오."
L["Your Marker"] = "내 징표"
L["Your Masque skins on Arc Auras icons, aura icons included: pick one per icon group in Masque."] = "Arc Auras 아이콘(오라 아이콘 포함)에 Masque 스킨을 적용합니다. Masque에서 아이콘 그룹마다 하나씩 고르십시오."
L["Your Spells"] = "내 주문"
